WITH payload AS (SELECT $archive_payload$[{"id":"c8eb5ac9-abcb-5f3e-ba2d-8a3eedcce0d5","document_type":"judgment","category":"judicial","subcategory":"general","title":"بيع -بيع قطعة أرض وقبض جزء من الثمن -وهمية األرض- مطالبة املدعى عليه بإعادة املبلغ -الدفع بأن املبلغ مقابل أتعاب -حلف املدعي اليمن بأن املبلغ املدفوع جزء من ثمن األرض - احلكم بإعادة املبلغ املدفوع .","document_number":"34247697","case_number":"3491200","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بخميس مشيط","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/6/20","year":"1434","subject":"بيع -بيع قطعة أرض وقبض جزء من الثمن -وهمية األرض- مطالبة املدعى عليه بإعادة املبلغ -الدفع بأن املبلغ مقابل أتعاب -حلف املدعي اليمن بأن املبلغ املدفوع جزء من ثمن األرض - احلكم بإعادة املبلغ املدفوع .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫تاريخه‪1434/6/20 :‬هـ‬\n                 ‫ُ‬                ‫َر ْق ُم َّ‬\n                    ‫الص ِّك‪34247697 :‬‬\n                    ‫َر ْق ُم الدعوى‪3491200 :‬‬\n    ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n          ‫‪ 34341903‬تاريخه‪1434/10/27 :‬هـ‬\n\n\n‫بيــع ‪ -‬بيــع قطعــة أرض وقبــض جــزء مــن الثمــن ‪ -‬وهميــة األرض‪-‬‬\n‫مطالبــة املدعــى عليــه بإعــادة املبلــغ ‪ -‬الدفــع بــأن املبلــغ مقابــل أتعــاب‬\n‫‪ -‬حلــف املدعــي اليمــن بــأن املبلــغ املدفــوع جــزء مــن ثمــن األرض ‪-‬‬\n                                               ‫احلكــم بإعــادة املبلــغ املدفــوع ‪.‬‬\n\n\n\n‫قــول الرســول صلــى اهلل عليــه وســلم ( البينــة علــى املدعــي واليمــن‬\n                                                        ‫علــى مــن أنكــر ) ‪.‬‬\n\n\n\n‫ادعــى املدعــي وكالــة بــأن موكلــه اشــترى قطعــة أرض وســلم جــزء‬\n‫مــن ثمنهــا للمدعــى عليــه لتســليمها إلــى مالــك هــذه األرض‪ ،‬كمــا‬\n‫قــام بإعطــاء املدعــى عليــه وكالــة شــرعية مــن أجــل إنهــاء اإلجــراءات‬\n‫النظاميــة لهــذه األرض وذلــك حســب طلبــه‪ ،‬وبعــد ذلــك اتضح أن األرض‬\n‫وهميــة وال حقيقــة لهــا علــى الطبيعــة فقــام بفســخ الوكالــة ومطالبــة‬\n‫املدعــى عليــه بإعــادة املبلــغ الــذي ســلمه إيــاه ‪ ،‬رفــض املدعــى عليــه إعادة‬\n‫املبلــغ بحجــة أن ذلــك املبلــغ مقابــل أتعــاب ‪ ،‬قــام املدعــي بحلــف اليمــن‬\n‫علــى أن املبلــغ املدفــوع للمدعــى عليــه جــزء مــن ثمــن األرض إليصالــه‬\n‫إلــى مالكهــا‪ ،‬حكمــت احملكمــة بإلــزام املدعــى عليــه بإعــادة املبلــغ‬\n‫‪ ،‬اعتــرض املدعــى عليــه علــى احلكــم ‪ ،‬صــدق احلكــم مــن محكمــة‬\n                                                                     ‫االســتئناف ‪.‬‬\n                                                                                       ‫‪276‬‬\n\f      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا (‪ )....‬القاضــي يف احملكمــة العامــة‬\n      ‫بخميــس مشــيط وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس‬\n      ‫احملكمة برقم ‪ 3491200‬وتاريخ ‪ 1434/02/24‬هـ املقيدة باحملكمة‬\n      ‫برقــم ‪ 34466074‬وتاريــخ ‪ 1434/02/24‬ه ـ ففــي ي ــوم األحـ ــد املوافــق‬\n      ‫‪ 1434/03/08‬ه ـ افتتحــت اجللســة الــساعـ ــة ‪ 10 : 00‬وفيهــا حضــر‬\n      ‫‪ ............‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم ‪ ............‬بصفتــه‬\n      ‫الوكيــل الشــرعي عــن ‪ ..............‬ســعودي اجلنســية مبوجــب الســجل‬\n      ‫املدنــي ‪ ..........‬وذلــك مبوجــب الوكالــة الشــرعية الصــادرة مــن كتابــة‬\n      ‫عــدل الباحــة برقــم ‪ 33404476‬يف ‪1433/09/06‬ه ـ والتــي تخولــه حــق‬\n      ‫مطالبــة املدعــو ‪ ...............‬وحــق املرافعــة واملدافعــة واإلقــرار واإلنــكار‬\n      ‫وحضــور اجللســات وقبــول احلكــم ونفيــه والصلــح واالســتالم وادعــى‬\n      ‫علــى احلاضــر معــه ‪ ...........‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم‬\n      ‫ا يف دعــواه إنــه قبــل حوالــي ســنة تقريبـ ًا اشــترى موكلــي‬  ‫‪ ...............‬قائـ ً‬\n      ‫أرضــا تقــع يف عمــق التابــع ملكــة املكرمــة عــن طريــق املدعــى عليــه‬\n      ‫احلاضــر مــن ‪ ....................‬بحســب كالم هــذا احلاضــر باجللســة مببلــغ‬\n      ‫إجمالــي وقــدره مليونــان ومائتــا ألــف ريــال مبوجــب أوراق حتمــل اســم ‪....‬‬\n      ‫وقــد قــام موكلــي بتســليم املدعــى عليــه مبلغ ـ ًا وقــدره مائتــان وثمانيــة‬\n      ‫وتســعون ألــف وخمســمائة ريــال كدفعــة مــن قيمــة األرض عــن طريــق‬\n      ‫حتويــل بنكــي وقــام موكلــي أيض ـ ًا بإعطــاء املدعــى عليــه وكالــة‬\n      ‫شــرعية بحســب طلبــه مــن أجــل إنهــاء اإلجــراءات النظاميــة لهــذه األرض‬\n      ‫وبعــد ذلــك اتضــح ملوكلــي عــدم صحــة األوراق وأن األرض وهميــة وال‬\n\n‫‪277‬‬\n\f‫حقيقــة لهــا علــى الطبيعــة وقــام بفســخ الوكالــة للمدعــى عليــه فــور ًا‬\n‫وإبالغــه بذلــك ومطالبتــه بإعــادة املبلــغ الــذي ســلمه إيــاه إال أنــه لــم ميتثــل‬\n‫ولــذا فإننــي اآلن أطالبــه بإعــادة املبلــغ الــذي ســلمه إيــاه موكلــي وقــدره‬\n‫مائتــان وثمانيــة وتســعون ألــف وخمســمائة ريــال هــذه دعــواي وبســؤال‬\n‫املدعــى عليــه عــن ذلــك قــال مــا ذكــره املدعــي وكالــة يف دعــواه غيــر‬\n‫صحيــح والصحيــح أن مــوكل هــذا احلاضــر قــام بشــراء مخطــط يقــع‬\n‫يف ‪ ....‬التابــع ملكــة املكرمــة مــن ‪ ...........‬عــن طريــق وكيلــه الشــرعي‬\n‫‪ .............‬وليــس عــن طريقــي أبــد ًا مببلــغ وقــدره مليونــان ومائتــا ألــف‬\n‫ريــال وبالفعــل اســتلمت منــه مبلغـ ًا وقــدره مائتــان وثمانيــة وتســعون ألــف‬\n‫وخمســمائة ريــال عــن طريــق حتويــل بنكــي مقابــل أتعابــي يف إثبــات‬\n‫املخطــط بعــد أن اتضــح للمشــتري عــدم صحــة وجــود مخطــط علــى‬\n‫الطبيعــة حيــث أنــه بعــد ذلــك قــام بتوكيلــي وكالــة شــرعية بعــد أن‬\n‫ســلم ‪ ....‬مبلغ ـ ًا وقــدره خمســمائة ألــف ريــال مبوجــب شــيكات وأمــا‬\n‫مــا ذكــره املدعــي وكالــة مــن قيــام موكلــه بفســخ توكليــه لــي فهــذا‬\n‫صحيــح ولكــن بعــد انتهــاء قضيــة مــوكل هــذا احلاضــر مــع ‪ ....‬لــدى‬\n‫هيئــة التحقيــق واالدعــاء العــام وعليــه فليــس لــه أي حــق يف مطالبتــي‬\n‫بهــذا املبلــغ هكــذا أجــاب وبعــرض ذلــك علــى املدعــي وكالــة قــال‬\n‫مــا ذكــره غيــر صحيــح والصحيــح مــا ذكــرت هكــذا قــال وبســؤال‬\n‫املدعــى عليــه عــن بينتــه علــى مــا ذكــر مــن أن املبلــغ الــذي اســتلمه‬\n‫مــن مــوكل املدعــي وقــدره مائتــان وثمانيــة وتســعون ألــف وخمســمائة‬\n‫ا أنــا مســتعد بإثبــات ذلــك يف اجللســة‬          ‫ريــال مقابــل أتعابــه أجــاب قائ ـ ً‬\n‫القادمــة ويف جلســة أخــرى وفيهــا حضــر املدعــي وكالــة واملدعــى عليــه‬\n‫وكنــا يف اجللســة الســابقة قــد طلبنــا مــن املدعــى عليــه إحضــار بينتــه‬\n\n\n                                                                                             ‫‪278‬‬\n\f      ‫علــى مــا ذكــر مــن أن املبلــغ الــذي اســتلمه مــن مــوكل املدعــي وقــدره‬\n      ‫مائتــان وثمامنائــة وتســعون ألــف وخمســمائة ريــال مقابــل أتعابــه فاســتعد‬\n      ‫بإحضارهــا يف هــذه اجللســة وبســؤاله عــن ذلــك أجــاب قائــا إن بينتــي‬\n      ‫تتمثــل يف قيــام املدعــي أصالــة بتوكيلــي وكالــة شــرعية صــادرة مــن‬\n      ‫كتابــة العــدل الثانيــة بالطائــف برقــم ‪ .....‬يف ‪1433/4/25‬ه ـ وذلــك مــن‬\n      ‫أجــل أن أقــوم باملداعــاة واملطالبــة بــاألرض التــي اشــتراها مــوكل هــذا‬\n      ‫احلاضــر مــن ‪ ................‬وذلــك بعــد أن اتضــح لــه أن األرض التي اشــتراها‬\n      ‫‪ ....‬ليــس لهــا وجــود علــى الطبيعــة وقــد قمــت بالدخــول علــى ســمو أميــر‬\n      ‫منطقــة مكــة املكرمــة وقدمــت إليــه اســتدعاء بطلــب إيقــاف الشــيك‬\n      ‫الــذي حــرر لصالــح ‪ ...........‬مببلــغ وقــدره مليــون وســبعمائة ألــف ريــال‬\n      ‫حتــى تتضــح األرض املشــتراه وبعــد ذلــك قــام بتحويــل االســتدعاء إلــى‬\n      ‫اجلهــات اإلداريــة وبعــد ذلــك قمــت باملراجعــة واملطالبــة وذلــك مــن أجــل‬\n      ‫احلصــول علــى األرض ومراجعــة جميــع الدوائــر احلكوميــة يف محافظــة‬\n      ‫جــدة والطائــف وكذلــك إمــارة منطقــة مكــة املكرمــة وبعــد مراجعتــي‬\n      ‫اتضــح عــدم وجــود حقيقــة لــأرض املشــتراه مــن قبــل املدعــي أصالــة ‪.‬‬\n      ‫وبعــرض ذلــك علــى املدعــي وكالــة قــال إن موكلــي قــام بتوكيــل هــذا‬\n      ‫احلاضــر مــن أجــل املطالبــة بــاألرض التــي اشــتراها مــن ‪..................‬عــن‬\n      ‫طريــق هــذا احلاضــر وملــا اتضــح ملوكلــي أنــه ال يوجــد لهــذه األرض‬\n      ‫حقيقــة قــام بفســخ وكالتــه بعــد واحــد وعشــرين يومــا مــن توكيلــه‬\n      ‫لــه وأمــا مــا ذكــره مــن أنــه قــام بإيقــاف الشــيك احملــرر مــن موكلــي‬\n      ‫لصالــح ‪ .................‬فــا صحــة لذلــك بــل قــام وكيــل ‪ ............‬بتســليم‬\n      ‫الشــيك املذكــور ملوكلــي يف محافظــة الطائــف هكــذا أجــاب وقــد‬\n      ‫رفعــت اجللســة عنــد الســاعة التاســعة النتهــاء وقتهــا ويف جلســة أخــرى‬\n\n\n‫‪279‬‬\n\f‫وفيهــا حضــر املدعــي وكالــة ولــم يحضــر املدعــى عليــه رغــم تبلغــه‬\n‫مبوعــد هــذه اجللســة لشــخصه وتوقيعــه عليــه بحســب ضبــط اجللســة‬\n‫الســابقة وبحســب ورقــة التبليــغ املؤرخــة يف ‪1434/04/29‬ه ـ ولــم يقــم‬\n‫املدعــى عليــه بإبــداء أي عــذر يف تخلفــه عــن هــذه اجللســة وعليــه فقــد‬\n‫قــررت الســير يف هــذه الدعــوى غيابي ـ ًا يف حــق املدعــى عليــه اســتناد ًا‬\n‫للمــادة (‪ )1/55‬مــن نظــام املرافعــات الشــرعية كمــا حضــر يف هــذه‬\n‫ا ‪ :‬إن جميــع مــا ذكــره‬   ‫اجللســة املدعــي أصالــة ‪ .........‬وقــد تلفــظ قائ ـ ً‬\n‫املدعــى عليــه غيــر صحيــح فلــم أقــم بتحويــل هــذا املبلــغ املذكــور مقابــل‬\n‫أتعابــه بــل قمــت بتحويــل هــذا املبلــغ علــى حســابه وذلــك مــن أجــل أن‬\n‫يقــوم بإيصــال هــذا املبلــغ ل‪ ......‬واســتالم صــك األرض املشــتراة وذلــك‬\n‫لكــون البيــع حصــل عــن طريقــه علم ـ ًُا أننــي قــد اتفقــت أنــا واملدعــى‬\n‫عليــه علــى أن أعطيــه ســعيه يف حــال إمتــام البيــع ولكــن عندمــا اتضــح‬\n‫لــي أنــه ال حقيقــة لهــذه األرض علــى الطبيعــة قمــت بفســخ وكالتــه بعــد‬\n‫مضــي واحــد وعشــرين يومـ ًا علمـ ًا أن املدعــى عليــه ذكــر بــأن مراجعتــه‬\n‫اســتمرت ملــدة ســنة وهــذا باطــل ثــم جــرى بعــد ذلــك عــرض اليمــن علــى‬\n‫املدعــي أصالــة علــى صحــة دعــواه فاســتعد بذلــك فجــرى تخويفــه بــاهلل‬\n‫تعالــى وحثــه علــى الصــدق وحتذيــره مــن اليمــن الكاذبــة فقــال إننــي‬\n‫أعلــم ذلــك وأنــا صــادق يف دعــواي ثــم جــرى حتليفــه بعــد أن أذنــت لــه‬\n‫ا ( واهلل العظيــم الــذي ال إلــه إال هــو عالــم الغيــب والشــهادة أن مــا‬  ‫قائـ ً‬\n‫ذكــره املدعــى عليــه مــن أن املبلــغ الــذي قمــت بتحويلــه لــه علــى حســابه‬\n‫وقــدره مائتــان وثمانيــة وتســعون ألــف وخمســمائة ريــال مقابــل أتعابــه أن‬\n‫هــذا غيــر صحيــح وأننــي إمنــا قمــت بتحويلــه لــه مــن أجــل أن يقــوم بإيصال‬\n‫هــذا املبلــغ ل‪ ..........‬واســتالم صــك األرض التــي مت شــراؤها وذلــك‬\n\n\n                                                                                        ‫‪280‬‬\n\f      ‫لكــون البيــع قــد حصــل عــن طريقــه واهلل العظيــم علــى ذلــك ) كمــا‬\n      ‫جــرى مــن قبلــي االطــاع علــى صكــي فســخ الوكالتــن املقــدم مــن قبل‬\n      ‫املدعــي أصالــة برقمــي ‪ 36596‬و ‪ 36610‬واملؤرخــن يف ‪1433/6/30‬ه ـ‬\n      ‫واملتضمنــن قيــام املدعــي أصالــة بفســخ الوكالتــن اللتــن قــام فيهــا‬\n      ‫بتوكيــل املدعــى عليــه وقــد تبــن أن مــدة الوكالــة األولــى الصــادرة مــن‬\n      ‫كتابــة عــدل الطائــف الثانيــة برقــم ‪ ....‬يف تاريــخ ‪1433/3/29‬ه ـ هــي‬\n      ‫ثالثــة أشــهر فقــط كمــا تبــن أن مــدة الوكالــة الثانيــة الصــادرة أيضــا‬\n      ‫مــن كتابــة عــدل الطائــف الثانيــة برقــم ‪ ....‬يف تاريــخ ‪1433/4/25‬ه ـ‬\n      ‫ـاء علــى مــا تقــدم مــن الدعــوي‬  ‫هــي شــهر وخمســة أيــام فقــط فبنـ ً‬\n      ‫واإلجابــة ومبــا أن املدعــى عليــه قــد طلــب منــه إحضــار بينــة علــى صحــة‬\n      ‫دعــواه ومبــا أنــه قــد اســتعد بذلــك ثــم ذكــر بينــة غيــر موصلــة ونظــر ًا‬\n      ‫لقــول الرســول صلــى اهلل عليــه وســلم ( البينــة علــى املدعــي واليمــن‬\n      ‫علــى مــن أنكــر ) ونظــر ًا ألنــه جــرى حتليــف املدعــي أصالــة علــى‬\n      ‫صحــة دعــواه مــن غيــر طلــب املدعــى عليــه وذلــك لتخلفــه عــن اجللســة‬\n      ‫رغــم تبلغــه بهــا لشــخصه وحســم ًا ملــادة النــزاع واخلصــام ونظــرا لكــون‬\n      ‫اليمــن تشــرع يف حــق أقــوى املتداعيــن ونظــرا لكــون املدعــى عليــه قــد‬\n      ‫ذكــر بــأن مــدة مراجعتــه يف هــذه األرض قرابــة ســنة وهــذا يناقــض مــدة‬\n      ‫الوكالتــن املدونــة ســلفا مــن جهــة ويناقــض مصادقتــه علــى علمــه بقيــام‬\n      ‫املدعــي أصالــة بفســخ وكالتــه يف اجللســة األولــى مــن جهــة أخــرى ولهــذا‬\n      ‫فقــد ألزمــت املدعــى عليــه ‪ ...........‬بتســليم املدعــي أصالــة مبلغــا وقــدره‬\n      ‫مائتــان وثمانيــة وتســعون ألــف وخمســمائة ريــال حــاال وبذلــك حكمــت‬\n      ‫واعتبــرت هــذا احلكــم يف حــق املدعــى عليــه حضوريــا وأمــرت بتســليمه‬\n      ‫صــورة مــن صــك احلكــم لتقــدمي اعتراضــه إذا رغــب ذلــك خــال املــدة‬\n\n\n‫‪281‬‬\n\f‫احملــددة نظامــا وقدرهــا ثالثــون يومــا مــن تاريخ تســلمه لهــا وإال فإن حقه‬\n‫يســقط يف االعتــراض ويكتســب احلكــم الصفــة القطعيــة إذا انتهــت‬\n‫املــدة ولــم يتقــدم باملعارضــة واختتمــت اجللســة عنــد الســاعة التاســعة‬\n‫وبــاهلل التوفيــق وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم‬\n‫وحــرر يف ‪ 1434/06/18‬ه ـ احلمــد هلل وحــده وبعــد فلــدي أنــا ‪.............‬‬\n‫القاضــي باحملكمــة العامــة بخميــس مشــيط ويف هــذا اليــوم األربعــاء‬\n‫املوافــق ‪1434/11/19‬ه ـ افتتحــت اجللســة الســاعة التاســعة صباح ـ ًا‬\n‫وقــد عــادت املعاملــة بخطــاب رئيــس محكمــة االســتئناف مبنطقــة‬\n‫عســير برقــم ‪ 341932801‬وتاريــخ ‪1434/11/06‬ه ـ مشــفوع ًا بهــا قــرار‬\n‫أصحــاب الفضيلــة قضــاة االســتئناف بالدائــرة احلقوقيــة الثالثــة رقــم‬\n‫‪ 34341903‬يف ‪1434/10/27‬ه ـ املتضمــن وبدراســة الصــك وصــورة‬\n‫ضبطــه والالئحــة االعتراضيــة وأوراق املعاملــة لــم يظهــر مــا يوجــب‬\n‫االعتــراض لــذا قررنــا املوافقــة علــى احلكــم قاضــي اســتئناف ‪.........‬‬\n‫ختمــه وتوقيعــه قاضــي اســتئناف ‪ ........‬ختمــه وتوقيعــه رئيــس الدائــرة‬\n‫‪ ..........‬ختمــه وتوقيعــه ولــذا فقــد جــرى إحلاقــه حتــى ال يخفــى وأمــرت‬\n‫بالتهميــش بذلــك علــى ســجله وبــاهلل التوفيــق وصلــى اهلل علــى نبينــا‬\n                                       ‫محمــد وعلــى آلــه وصحبــه وســلم وحــرر ‪.‬‬\n\n\n\n\n                                                                                     ‫‪282‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"17250706-b6cd-5618-b1f0-019e3dec82ff","source_page_start":276,"source_page_end":282,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"95c50f510b51f6d5a48c99019850c8b69a0cc0f31ab4214c132451eb59998015","normalized_text_hash":"cc01017f9674a0ae87c816525928f65d4644984c5de338b9d96a68e585bd77b0","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v1-p276-34247697"},{"id":"7207a118-f06b-595c-b079-efc827f2b9b7","document_type":"judgment","category":"judicial","subcategory":"general","title":"بيع -بيع أرض مقام عليها استراحة -الغرر يف البيع -األرض مخطط لألمانة موزع على املواطنن -بيع رغم عدم التملك - اإلزالة بسبب التعدي -بطان عقد البيع وإعادة الثمن .","document_number":"33413996","case_number":"32113953","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة مبكة املكرمة","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1433/9/17","year":"1434","subject":"بيع -بيع أرض مقام عليها استراحة -الغرر يف البيع -األرض مخطط لألمانة موزع على املواطنن -بيع رغم عدم التملك - اإلزالة بسبب التعدي -بطان عقد البيع وإعادة الثمن .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫تاريخه‪1433/9/17 :‬هـ‬\n                       ‫ُ‬                ‫َر ْق ُم َّ‬\n                          ‫الص ِّك‪33413996 :‬‬\n                         ‫َر ْق ُم الدعوى‪32113953 :‬‬\n          ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                  ‫‪ 3417423‬تاريخه‪1434/1/20 :‬هـ‬\n\n\n      ‫بيــع ‪ -‬بيــع أرض مقــام عليهــا اســتراحة ‪ -‬الغــرر يف البيــع ‪ -‬األرض‬\n      ‫مخطــط لألمانــة مــوزع علــى املواطنــن ‪ -‬بيــع رغــم عــدم التملــك ‪-‬‬\n            ‫اإلزالــة بســبب التعــدي ‪ -‬بطــان عقــد البيــع وإعــادة الثمــن ‪.‬‬\n\n\n\n\n      ‫‪ -1‬مــا رواه حكيــم ابــن حــزام قلــت يــا رســول اهلل يأتيني الرجل فيســألني‬\n      ‫البيــع ليــس عنــدي أبيعــه منــه ثــم أبتاعــه مــن الســوق‪ ،‬فقــال ال تبــع مــا‬\n                                                                          ‫ليــس عنــدك ‪.‬‬\n                                       ‫‪ -2‬قاعدة ‪ :‬تعاطي العقود الفاسدة حرام ‪.‬‬\n\n\n\n\n      ‫ادعــى املدعــي بأنــه اشــترى قطعــة أرض مقــام عليهــا اســتراحة‪،‬‬\n      ‫اكتشــف أن كامــل املنطقــة مخطــط ألمانــة العاصمــة وموزعــة علــى‬\n      ‫املواطنــن‪ ،‬طلــب احلكــم بفســخ البيــع وإعــادة كامــل الثمــن‪ ،‬صــادق‬\n      ‫املدعــى عليــه علــى الدعــوى وأقّ ــر مبعرفتــه وقــت البيــع بــأن األرض‬\n      ‫مخطــط ‪ ،‬مــن كل ذلــك ونظــر ًا ألن املدعــى عليــه قــد بــاع مــا ال ميلــك‬\n      ‫حكمــت احملكمــة ببطــان عقــد البيــع وإعــادة ثمــن البيــع ‪ ،‬اعتــرض‬\n      ‫املدعــى عليــه علــى احلكــم ‪ ،‬صــدق احلكــم مــن محكمــة االســتئناف ‪.‬‬\n\n\n‫‪283‬‬\n\f‫احلمد هلل وحده وبعد فلدي أنا (‪ )....‬القاضي يف احملكمة العامة مبكة‬\n‫املكرمــة وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n‫العامــة مبكــة املكرمــة برقــم ‪ 32113953‬وتاريــخ ‪ 1432/04/08‬ه ـ‬\n‫املقيــدة باحملكمــة برقــم ‪ 32353554‬وتاريخ ‪ 1432/04/08‬هـ املتعلقة‬\n‫بدعــوى ‪ ....‬ففــي هــذا اليــوم األحــد ‪ 1432/07/03‬ه ـ افتتحــت اجللســة‬\n‫الســاعة ‪ 09 : 00‬وفيهــا حضــر ‪ .......‬ســعودي اجلنســية مبوجــب الســجل‬\n‫املدنــي رقــم ‪ .......‬وحضــر حلضــوره املدعــى عليــه ‪ .......‬بالســجل املدنــي‬\n‫ا يف حتريــر‬ ‫رقــم ‪ .......‬ثــم ادعــى املدعــي يف مواجهــة املدعــى عليــه قائ ـ ً‬\n‫علي اســتراحة تقع يف صعيد قريش‬       ‫دعــواه عليــه إن هــذا احلاضــر قــد بــاع ّ‬\n‫مبدينــة مكــة املكرمــة وذلــك بتاريــخ ‪1431/3/17‬ه ـ تبلــغ مســاحتها‬\n‫(‪ 725‬م‪ )2‬ويحدهــا شــما ًال مســجد وجنوب ـ ًا قطعــة رقــم(‪ )47‬وشــرق ًا‬\n‫قطعــة رقــم(‪ )46‬وغرب ـ ًا شــارع عــرض اثنــا عشــر متــر بقيمــة إجماليــة‬\n‫قدرهــا خمســة وخمســون ألــف ريــال اســتلمها بالكامــل إال أنــه بعد ســنة‬\n‫مــن تاريــخ البيــع ظهــر بــأن كامــل املنطقــة ألمانــة العاصمــة املقدســة‬\n‫مخططــة وموزعــة علــى شــكل منــح ســكنية للمواطنــن فقامــت األمانة‬\n‫بهــدم االســتراحة حســب مطالبــة املواطــن الذي منــح ذات األرض مكان‬\n‫االســتراحة مبوجــب صــك شــرعي ونظــر ًا ألن املدعــى عليــه قــد غرنــي‬\n‫بصنيعــه ذلــك حيــث بــاع علـ ّـي أرض ـ ًا مخططــة لألمانــة واســتلم نظيــر‬\n‫ذلــك املبلــغ املالــي املذكــور أعــاه فإنــي أطلــب احلكــم عليــه بفســخ‬\n‫البيــع وإعــادة كامــل املبلــغ الــذي دفعتــه لــه وقــدره خمســة وخمســون‬\n‫ألــف ريــال حــا ًال هــذه دعــواي وأســأله اجلــواب وبعــرض ذلــك علــى املدعــى‬\n\n                                                                                      ‫‪284‬‬\n\f      ‫عليــه أجــاب بقولــه مــا ذكــره املدعــي مــن بيعــي عليــه العقــار املوصــوف‬\n      ‫يف دعــواه بالثمــن املذكــور بهــا واســتالمي لــه فصحيــح وال أنكــره غيــر‬\n      ‫أنــي يف حينهــا أعنــي حــن البيــع بعــت تلــك االســتراحة وهــي مملوكــة‬\n      ‫لــي مبوجــب وثيقــة متلــك وهــو يعــرف ذلــك وقــد أعطيتهــا لــه وأمــا عــن‬\n      ‫طلبــه إعــادة املبلــغ املســلم لــه املدعــى بــه فإنــي لــن أعيــده لــه ألن البيــع‬\n      ‫وقــع صحيح ـ ًا وأنــا كحالــه اشــتريت املوقــع مــن شــخص آخــر مبوجــب‬\n      ‫وثيقــة كذلــك هكــذا أجــاب‪ ،‬ثــم ســألت املدعــى عليــه عمــا ذكــره‬\n      ‫املدعــي مــن كــون األرض محــل النــزاع هــي مخطــط لألمانــة وموزعــة‬\n      ‫علــى املواطنــن وأن األمانــة قامــت بهــدم االســتراحة بنــاء علــى طلــب‬\n      ‫املواطــن املمنــوح لــه تلــك األرض القائمــة عليهــا فأجــاب قائــا مــا ذكــره‬\n      ‫املدعــي مــن هــدم االســتراحة مــن قبــل أمانــة العاصمــة فصحيــح حيــث‬\n      ‫هدمــت جميــع االســتراحات الواقعــة يف صعيــد قريــش وأمــا عــن مــدى‬\n      ‫تخطيطهــا فقــد علمــت أنهــا ســتصير مخطــط وذلــك قبل بيع االســتراحة‬\n      ‫علــى املدعــي ولكــن ال أعلــم متــى ســيكون التخطيــط بالتحديــد‬\n      ‫هكــذا قــال وبعــرض ذلــك علــى املدعــي أجــاب قائــا إن الصحيــح هــو‬\n      ‫مــا ذكرتــه مــن قبــل وال إجابــة لــي علــى مــا قدمتــه هكــذا أجــاب ثــم‬\n      ‫قــررت الكتابــة ألمانــة العاصمــة املقدســة لإلفــادة عــن تلــك األرض وهل‬\n      ‫قامــت بتخطيطهــا وهــل مت توزيعهــا كمنــح علــى املواطنــن بصكــوك‬\n      ‫شــرعية ثــم عــادت إلينــا مــن أمانــة العاصمــة املقدســة رفــق خطابهــا‬\n      ‫رقــم ‪ 322028136‬يف ‪1432/10/7‬ه ـ املتضمــن (أن املوقــع مــن ضمــن‬\n      ‫التعديــات التــي ســبق وان أزيلــت مــن قبــل البلديــة ومبشــاركة اجلهــات‬\n      ‫األمنيــة املختصــة حســب توجيــه مقــام األمــارة رقــم ‪/109584‬ص‪/‬خ يف‬\n      ‫‪1431/12/10‬ه ـ املرفــق صورتــه) اهــ‪ .‬وبعرضــه علــى املتداعيــن أجابــا‬\n\n\n‫‪285‬‬\n\f‫قائلــن إن مــا ورد يف خطــاب األمانــة هــو الصحيــح وهــو املطابــق للواقــع‬\n‫هكــذا قــاال فبنــاء علــى مــا تقــدم مــن الدعــوى واإلجابــة وإلقــرار املدعــى‬\n‫عليــه بحصــول البيــع علــى العــن املوصوفــة يف الدعــوى واســتالمه للثمــن‬\n‫املذكــور بهــا وعــدم إنــكاره لشــيء مــن ذلــك وإلقــراره بأنــه كان‬\n‫يعلــم عــن تخطيــط األرض قبــل بيــع االســتراحة علــى املدعــي وملــا ورد‬\n‫يف قــرار أمانــة العاصمــة املقدســة املرصــودة برقمــه وتاريخــه ســلفا مــن‬\n‫أن املوقــع مــن ضمــن التعديــات التــي ســبق وأن أزيلــت مــن قبــل البلديــة‬\n‫ومبشــاركة اجلهــات األمنيــة املختصــة حســب توجيــه األمــارة وإلقــرار‬\n‫املتداعيــن بــأن مــا ورد يف خطــاب األمانــة صحيــح ومطابــق للواقــع وألن‬\n‫املدعــى عليــه بإقــراره بــكل مــا تقــدم يعــد قــد بــاع مــا ال ميلــك وألن مــن‬\n‫شــروط صحــة البيــع أن يكــون مــن مالــك أو مــن يقــوم مقامــه (وملــا رواه‬\n‫حكيــم بــن حــزام قــال قلــت يــا رســول اهلل يأتينــي الرجــل فيســألني‬\n‫البيــع ليــس عنــدي أبيعــه منــه ثــم ابتاعــه مــن الســوق فقــال ال تبــع مــا ليــس‬\n‫عنــدك) رواه اخلمســة وصححــه الترمــذي وألن عقــد البيــع بتخلــف ذلــك‬\n‫الشــرط يعــد فاســدا قــال الســيوطي (القاعــدة اخلامســة تعاطــي العقــود‬\n‫الفاســدة حــرام) األشــباه والنظائــر ‪ 111/2‬لــكل ذلــك فقــد تبــن لــي‬\n‫بطــان عقــد البيــع املبــرم بــن املتداعيــن وحكمــت علــى املدعــى عليــه‬\n‫‪ ......‬بــأن يعيــد للمدعــي ‪ .....‬املبلــغ املدعــى بــه وقــدره خمســة وخمســون‬\n‫ألــف ريــال وبذلــك حكمــت وبعرضــه علــى املدعــى عليــه قــرر اعتراضــه‬\n‫عليــه فجــرى إفهامــه مبراجعــة احملكمــة خــال عشــرة أيــام الســتالم‬\n‫نســخة مــن احلكــم لتقــدمي اعتراضــه عليــه خــال ثالثــن يومــا مــن‬\n‫تاريــخ االســتالم فــإن لــم يفعــل خاللهــا فــإن حقــه يف االعتــراض يســقط‬\n‫ويكتســب احلكــم القطعيــة وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا‬\n           ‫محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪1433/09/09‬ه ـ ‪.‬‬\n‫•صــدق احلكــم مــن محكمــة االســتئناف برقــم ‪ 3417423‬وتاريــخ‬\n                                               ‫‪1434/1/20‬هــ‪.‬‬\n\n                                                                                           ‫‪286‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"17250706-b6cd-5618-b1f0-019e3dec82ff","source_page_start":283,"source_page_end":286,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"d52130e792010900d39bd609bda40eb62bf9c2543f9facad865e41c8a3105e54","normalized_text_hash":"51d61b06397301b414af4937edfa1902b94af6b05d7e6147f82737da5de5003d","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v1-p283-33413996"},{"id":"966d2587-cb0d-579f-b2bc-c605b82c8b5c","document_type":"judgment","category":"judicial","subcategory":"general","title":"بيع -عقد -بيع أرض -ارش النقص لعيب يف األرض املباعة - تقدير ارش النقص عن طريق قسم اخلبراء -إذا وجد عيب يف املبيع فللمشتري اخليار بن إمساكه مع األرش أو الفسخ -احلكم مببلغ مقدر وصرف النظر عن غيره من طلبات -احلكم حضوري ا لتبلغ املدعى عليه .","document_number":"34176732","case_number":"32189741","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة مبحافظة االحساء ب","circuit":"الدائرة وعليه توقيع وختم لكل واحد منهم وعليه أجيب أصحاب","issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/4/1","year":"1434","subject":"بيع -عقد -بيع أرض -ارش النقص لعيب يف األرض املباعة - تقدير ارش النقص عن طريق قسم اخلبراء -إذا وجد عيب يف املبيع فللمشتري اخليار بن إمساكه مع األرش أو الفسخ -احلكم مببلغ مقدر وصرف النظر عن غيره من طلبات -احلكم حضوري ا لتبلغ املدعى عليه .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫تاريخه‪1434/4/1 :‬هـ‬\n                     ‫ُ‬                  ‫َر ْق ُم َّ‬\n                          ‫الص ِّك‪34176732 :‬‬\n                         ‫َر ْق ُم الدعوى‪32189741 :‬‬\n         ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n               ‫‪ 35116711‬تاريخه‪1435/1/16 :‬هـ‬\n\n\n      ‫بيــع ‪ -‬عقــد ‪ -‬بيــع أرض ‪ -‬ارش النقــص لعيــب يف األرض املباعــة ‪-‬‬\n      ‫تقديــر ارش النقــص عــن طريــق قســم اخلبــراء ‪ -‬إذا وجــد عيــب يف‬\n      ‫املبيــع فللمشــتري اخليــار بــن إمســاكه مــع األرش أو الفســخ ‪ -‬احلكــم‬\n      ‫مببلــغ مقــدر وصــرف النظــر عــن غيــره مــن طلبــات ‪ -‬احلكــم حضوريـ ًا‬\n                                                          ‫لتبلــغ املدعــى عليــه ‪.‬‬\n\n\n\n\n      ‫‪ -1‬إذا ظهــر يف املبيــع عيــب فاملشــتري مخيــر بــن فســخ البيــع أو‬\n      ‫إمســاكه مــع أرش نقصــه وهــو املذهــب‪ .‬نــص عليــه يف كشــاف القنــاع‪.‬‬\n                          ‫‪ -2‬املواد (‪ )55‬و(‪ )56‬من نظام املرافعات الشرعية ‪.‬‬\n\n\n\n\n      ‫أدعــى املدعــي بأنــه اشــترى أرضـ ًا مــن املدعى عليه وبعد الرفع املســاحي‬\n      ‫لهــا تبــن أن مســاحتها أقــل مــن املســاحة املذكــورة يف صــك امللكيــة ‪،‬‬\n      ‫ولــذا فقــد طلــب إلــزام املدعــى عليــه بــأرش نقــص األرض ‪ ،‬أقــر املدعــى‬\n      ‫عليــه مبــا جــاء يف الدعــوى مــن البيــع والشــراء والثمــن واملثمــن ودفــع بأنــه‬\n      ‫ال علــم لــه بالنقــص احلاصــل عليهــا ‪ ،‬قــررت احملكمــة الكتابــة لقســم‬\n      ‫اخلبــراء لتقديــر أرش النقــص بســبب العيــب املذكــور ‪ ،‬املشــتري مخيــر‬\n      ‫بــن فســخ البيــع أو إمســاكه مــع أرش نقصــه إن بــان معيبــا وقــد طالــب‬\n\n‫‪287‬‬\n\f‫املدعــي بــأرش النقــص احلاصــل علــى أرضــه محــل البيــع مــن املدعــى‬\n‫عليــه ‪ ،‬قضــت احملكمــة حضوريـ ًا بإلــزام املدعــى عليــه بتســليم املدعــي‬\n‫قيمــة األرش املقــدرة مــن أهــل اخلبــرة وصرفــت النظــر عمــا زاد عــن ذلــك‬\n‫وللمدعــى عليــه الرجــوع علــى مــن باعــه ‪ ،‬عــارض املدعــي واملدعــى عليــه‬\n   ‫علــى احلكــم ‪ ،‬قــررت محكمــة االســتئناف املصادقــة علــى احلكــم ‪.‬‬\n\n\n\n\n‫العامــة‬\n   ‫ّ‬       ‫احلمــد هلل وحــده وبعــد فلــدي أنــا (‪ )....‬القاضــي يف احملكمــة‬\n‫باألحســاء وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n‫العامــة مبحافظــة االحســاء برقــم ‪ 32189741‬وتاريــخ ‪1432/05/22‬ه ـ‬\n‫املقيــدة باحملكمــة برقــم ‪ 32593080‬وتاريــخ ‪ 1432/05/22‬ه ـ حضــر‬\n‫املدعــي (‪ )........‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم (‪)........‬‬\n‫واملدعــى عليــه (‪ )........‬الســعودي بالســجل املدنــي رقــم (‪ )........‬وبســؤال‬\n‫املدعــي عــن دعــواه قــال لقــد قمــت بشــراء أرض مــن املدعــى عليــه تقــع‬\n‫يف قريــة (‪ )........‬التابعــة ملركــز (‪ )........‬ومســاحتها ســبعمائة متــر‬\n‫مربــع ‪700‬م‪ 2‬اململوكــة لــي بالصــك رقــم ‪ 189‬يف ‪1430/11/12‬ه ـ‬\n‫الصــادر مــن كتابــة عــدل العيــون بالشــراء مــن هــذا احلاضــر بتاريــخ‬\n‫‪1432/5/2‬ه ـ واحملــدودة شــما ًال بالقطعــة ‪ 64‬وجنوب ـ ًا بالقطعــة ‪68‬‬\n‫وغرب ـ ًا بالقطعــة ‪ 65‬وشــرق ًا شــارع باملســاحة املذكــورة بعاليــه بثمــن‬\n‫وقــدره مائتــان وســبعون ألــف ريـ‪ 270000‬ــال ثــم قمــت بتركيــز األرض‬\n‫لــدى مكتــب (‪ )........‬الهندســي وتبــن بــأن األرض مســاحتها علــى أرض‬\n‫الواقــع خمســمائة وثالثــون متــر ًا مربع ـ ًا وســبعة وتســعون ســنتيمترا‬\n‫‪530.97‬م‪ 2‬بنقــص قــدره مائــة وتســعة وســتون متــر ًا وثالثــة ســنتيمترات‬\n\n                                                                                    ‫‪288‬‬\n\f      ‫‪169.3‬م أطلــب إلــزام املدعــى عليــه بــأرش نقــص األرض وال أطلــب فســخ‬\n      ‫البيــع كمــا جــاء يف صحيفــة الدعــوى هــذه دعــواي وبعــرض ذلــك علــى‬\n      ‫املدعــى عليــه قــال مــا جــاء يف دعــوى املدعــي مــن البيــع والشــراء والثمــن‬\n      ‫واملثمــن فكلــه صحيــح وقــد آلــت إلـ َّـي األرض بالشــراء مــن املدعــو‬\n      ‫(‪ )........‬بتاريــخ ‪1431/12/29‬ه ـ علــى مســاحة قدرهــا ســبعمائة متــر‬\n      ‫مربــع ‪700‬م‪ 2‬وال علــم لــي بالنقــص احلاصــل عليهــا وقــد اســتلمت صــك ًا‬\n      ‫مكتمــل اإلجــراءات هكــذا أجــاب وعليــه فقــد جــرى االستفســار عــن‬\n      ‫ســريان مفعــول الصــك ‪ 1089‬فــورد اجلــواب مــن كتابــة عــدل العيــون‬\n      ‫برقــم ‪ 830‬يف ‪1432/9/7‬ه ـ بــأن الصــك ســاري املفعــول ومطابــق‬\n      ‫لســجله وعليــه فقــد قــررت مخاطبــة بلديــة مركــز العيــون لإلفــادة عــن‬\n      ‫املســاحة احلقيقــة لــأرض علــى حســب الواقــع وإذا كانــت املســاحة‬\n      ‫ناقصــة فتبــن احلــدود واألطــوال واملســاحة احلقيقــة والســبب يف ذلــك ويف‬\n      ‫جلســة أخــرى حضــر املدعــي ولــم يحضــر املدعــى عليــه مــع تبلغــه مبوعــد‬\n      ‫هــذه اجللســة عــن طريــق ابــن أخيــه مبوجــب ورقــة التبليــغ املوقعــة مــن‬\n      ‫محضــر اخلصــوم وكان قــد وردنــا جــواب أمــن األحســاء رقــم ‪4601‬‬\n      ‫يف ‪1433/03/09‬ه ـ ونصــه إشــارة إلــى خطابكــم رقــم ‪321605088‬‬\n      ‫وتاريــخ ‪1432/12/23‬ه ـ بشــأن دعــوى املواطــن (‪ )........‬ســجل مدنــي‬\n      ‫رقــم (‪ )........‬ضــد املواطــن (‪ )........‬ســجل مدنــي رقــم (‪ )........‬على األرض‬\n      ‫رقــم (‪ )........‬باملخطــط رقــم (‪ )........‬والعائــدة مبوجــب الصــك رقم ‪1089‬‬\n      ‫لعــام ‪1430‬ه ـ عليــه نفيدكــم أن مســاحة األرض املذكــورة حســب‬\n      ‫الطبيعــة ‪530.97‬م‪ 2‬خمســمائة وثالثــون متــر ًا مربع ـ ًا وســبعة وتســعون‬\n      ‫عمــا بالصــك مبقــدار ‪169.03‬م‪ 2‬أمــا ســبب‬    ‫ســنتيمتر ًا مربعـ ًا أي بنقــص ّ‬\n      ‫هــذا النقــص فــإن عمليــة تركيــز املخطــط متــت بعــد املنــح وإصــدار‬\n\n\n‫‪289‬‬\n\f‫الصكــوك وبهــذا تكــون األراضــي عرضــة للزيــادة أو النقــص علم ـ ًا‬\n‫أن النقــص املشــار إليــه يف حــدود النســبة املســموح بهــا يف املنــح كمــا‬\n‫جــرى الكتابــة لرئيــس كتابــة عــدل العيــون برقــم ‪ 321119852‬يف‬\n‫‪1432/8/29‬ه ـ فــورد اجلــواب برقــم ‪ 830‬يف ‪1432/09/07‬ه ـ املتضمــن‬\n‫أن الصــك ســاري املفعــول ومطابــق لســجله انتهــى املقصــود ويف جلســة‬\n‫أخــرى حضــر املدعــي ولــم يحضــر املدعــى عليــه مــع تبلغــه مبوعــد هــذه‬\n‫اجللســة بنفســه مبوجــب ورقــة التبليــغ الــواردة إلينــا مــن محضــر اخلصــوم‬\n‫(‪ )........‬وبتأمــل مــا ســبق ونظــر ًا لكــون املدعــي قــد اختــار إمســاك‬\n‫املبيــع وطالــب بــأرش النقــص فقــد قــررت إحالــة املعاملــة لهيئــة اخلبــراء‬\n‫باحملكمــة لتحديــد أرش النقــص يف األرض محــل الدعــوى ويف جلســة‬\n‫أخــرى حضــر املدعــي املذكــورة هويتــه ســابق ًا ولــم يحضــر املدعــى عليه‬\n‫مــع تبلغــه مبوعــد هــذه اجللســة مبوجــب ورقــة التبليــغ الــواردة إلينــا مــن‬\n‫محضــر اخلصــوم (‪ )........‬واملوقــع عليهــا مــن قبــل ابــن عــم املدعــى عليــه‬\n‫وقــد عــادت املعاملــة مــن قســم اخلبــراء مبوجــب قرارهــم رقــم ‪ 871‬وتاريــخ‬\n‫‪1433/11/9‬ه ـ ونــص املقصــود منــه بعــد دراســة املعاملــة ومالحظــة‬\n‫املطلــوب وهــو تقديــر األرش لنقــص يف املســاحة الــذي مت عليــه الشــراء‬\n‫املســاحة ‪700‬م هــذا مــا يف الصــك ويف الطبيعــة ‪ 530.97‬والنقــص ‪169‬م‬\n‫نقــدر األرش املطلــوب الــذي يســتحقه املشــتري مــن البائــع مبلغ ـ ًا قــدره‬\n‫خمســون ألفـ ًا وســبعمائة ريــال فقــط ال غيــر عضــوا قســم اخلبــراء (‪)........‬‬\n‫و (‪ )........‬انتهــى املقصــود منــه وبعــرض القــرار علــى املدعــي قــال إننــي ال‬\n‫أقبــل بهــذا التقديــر ألننــي اشــتريت األرض وكان ســعر املتــر أكبــر مــن‬\n‫هــذا املبلــغ فاملبلــغ الــذي أســتحقه هــو خمســة و ســتون ألــف ريــال لكــون‬\n‫ســعر املتــر ثالثمائــة وخمســة وثمانــن ريــال هكــذا أجــاب فأفهمتــه بــأن‬\n\n\n                                                                                       ‫‪290‬‬\n\f      ‫ـاء على ما تقدم مــن الدعوى واإلجابة‬      ‫تقديــر ذلــك يرجــع ألهــل اخلبــرة فبنـ ً‬\n      ‫وحيــث طالــب املدعــي بــأرش النقــص احلاصــل على أرضه محــل البيع من‬\n      ‫املدعــى عليــه ولكــون املشــتري مخيــر ًا بــن فســخ البيــع أو إمســاكه مــع‬\n      ‫أرش نقصــه وهــو املذهــب كمــا نــص عليــه يف كشــاف القنــاع وحيــث‬\n      ‫قــدر أهــل اخلبــرة األرش وهــو قســط مــا بــن قيمــة الصحيــح واملعيــب‬\n      ‫ومــرد ذلــك ألهــل اخلبــرة لذلــك كلــه فقــد حكمــت بإلــزام املدعــى عليــه‬\n      ‫بتســليم املدعــي مبلغ ـ ًا وقــدره خمســون ألف ـ ًا وســبعمائة ريــال وصرفــت‬\n      ‫النظــر فيمــا زاد عــن ذلــك وهــذا احلكــم يف حــق املدعــى عليــه يعتبــر‬\n      ‫حكمـ ًا حضوريـ ًا لعلــم املدعــى عليــه مبواعيــد اجللســات مبوجــب املــادة‬\n      ‫‪ 55‬و‪ 56‬مــن نظــام املرافعــات الشــرعية وســيتم إفهامــه باحلكــم وحقــه‬\n      ‫يف االعتــراض ومدتــه وبعــرض احلكــم علــى املدعــي قــرر املعارضــة عليــه‬\n      ‫وطلــب محكمــة االســتئناف وأفهــم باملراجعــة بتاريــخ ‪1434/3/28‬ه ـ‬\n      ‫الســتالم نســخة مــن احلكــم وأفهمتــه باملــدة النظاميــة لالعتــراض وهــي‬\n      ‫ثالثــون يوم ـ ًا مــن تاريــخ اســتالمه نســخة احلكــم وأنهــا إذا مضــت هــذه‬\n      ‫املــدة دون تقــدمي االعتــراض ســقط حقــه يف طلــب االســتئناف وبــاهلل‬\n      ‫التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪.‬‬\n                                                         ‫حــرر يف ‪ 1434/03/17‬ه ـ ‪.‬‬\n      ‫احلمــد هلل وحــده وبعــد يف يــوم االثنــن تاريــخ ‪1434/7/24‬ه ـ فقــد‬\n      ‫وردت املعاملــة مــن محكمــة االســتئناف باملنطقــة الشــرقية برقــم‬\n      ‫‪34/1125336‬يف ‪1434/6/26‬ه ـ املقيــدة يف هــذه احملكمــة برقــم‬\n      ‫‪ 34/1125336‬يف ‪1434/6/28‬ه ـ وبرفقهــا القــرار الصــادر مــن‬\n      ‫أصحــاب الفضيلــة قضــاة دائــرة األحــوال الشــخصية الثانيــة رقــم‬\n      ‫‪/34249168‬ش‪ 2/‬يف ‪1434/6/24‬ه ـ نــص املقصــود منــه بدراســة‬\n\n\n‫‪291‬‬\n\f‫الصــك وصــورة ضبطــه والالئحــة االعتراضيــة وأوراق املعاملــة لوحــظ‬\n‫مــا يلــي أوالً‪ :‬أن فضيلــة القاضــي لــم يبلــغ املدعــى عليــه باحلكــم ويطبــق‬\n‫بشــأنه التعليمــات لتقــدمي الئحــة اعتراضــه عليــه مــن عدمــه والبــد مــن‬\n‫ذلــك ‪ .‬ثاني ـاً‪ :‬لــم يصــادق فضيلتــه علــى بعــض الصــور والوثائــق املرفقــة‬\n‫مبطابقتهــا ألصلهــا‪ .‬ثالث ـاً‪ :‬أن فضيلتــه كتــب لهيئــة النظــر يف تقديــر‬\n‫قيمــة النقــص احلاصــل يف االرض ومبــا أن قيمــة شــراء األرض معلومــة‬\n‫واألمتــار معلومــة وعليــه فــإن قيمــة النقــص الــذي حصــل معلومة بحســاب‬\n‫ســعر املتــر حســب الشــراء وإنقاصــه مــن كامــل القيمــة وال داعــي إلــى‬\n‫هيئــة النظــر لكونــه لــم يكــن مجهــو ًال الســيما وأن بــن تاريــخ املبايعــة‬\n‫وتاريــخ التركيــز وقتـ ًا قصيــراً‪ .‬رابعـاً‪ :‬لــم يذكــر فضيلتــه أن للمدعــى‬\n‫عليــه حــق الرجــوع علــى مــن باعــه‪ .‬فعلــى فضيلتــه مالحظــة مــا أشــير‬\n‫إليــه وإحلــاق مــا يجــد يف الصــك وضبطــه وســجله ومــن ثــم إعــادة املعاملــة‬\n‫إلكمــال الزمهــا واهلل املوفــق قضــاة محكمــة االســتئناف وهــم ورئيــس‬\n‫الدائــرة وعليــه توقيــع وختــم لــكل واحــد منهــم وعليــه أجيــب أصحــاب‬\n‫الفضيلــة علــى امللحوظــة االولــى بأنــه متــت الكتابــة مــن الرئيــس‬\n‫محضــري اخلصــوم باحملكمــة برقــم ‪ 3416777224‬يف ‪1434/7/11‬ه ـ‬\n‫لتســليم املدعــى عليــه نســخة مــن احلكــم لتقــدمي اعتراضــه عليــه يف املــدة‬\n‫املقــررة نظام ـ ًا فــورد اجلــواب برقــم ‪ 341677224‬يف ‪1434/7/12‬ه ـ‬\n‫بأنــه قــد مت تســليم املدعــى عليــه نســخة احلكــم بتاريــخ ‪1434/7/12‬ه ـ‬\n‫وقــد وردتنــا الالئحــة االعتراضيــة املقدمــة مــن املدعــى عليــه املقيــدة يف‬\n‫هــذه احملكمــة برقــم ‪ 341693910‬يف ‪1434/7/12‬ه ـ وجــرى االطــاع‬\n‫عليهــا ولــم أجــد مــا يوجــب الرجــوع وأمــا امللحوظــة الثانيــة فقــد مت‬\n‫ال وأمــا‬\n        ‫عمــل الــازم وأمــا امللحوظــة الثالثــة فســيتم تــدارك ذلــك مســتقب ً‬\n\n\n                                                                                     ‫‪292‬‬\n\f      ‫اجلــواب علــى امللحوظــة الرابعــة فقــد قــررت أن للمدعــى عليــه الرجــوع‬\n      ‫علــى مــن باعــه وأمــرت باحلــاق ذلــك يف صكــه وســجله ثــم إعــادة املعاملــة‬\n      ‫حملكمــة االســتئناف وللبيــان حــرر يف ‪1434/7/24‬ه ـ وصلــى اهلل علــى‬\n                                            ‫نبينــا محمــد وعلــى الــه وصحبــه وســلم‪.‬‬\n      ‫احلمــد هلل وحــده وبعــد ‪ ...‬فقــد اطلعنــا نحــن قضــاة دائــرة األحــوال‬\n      ‫الشــخصية الثانيــة يف محكمــة االســتئناف باملنطقــة الشــرقية علــى‬\n      ‫املعاملــة املقيــدة لــدى احملكمــة برقــم ‪/2191343/34‬ش‪ 2‬وتاريــخ‬\n      ‫‪1434/9/15‬ه والــواردة مــن فضيلــة رئيــس احملكمــة العامــة مبحافظــة‬\n      ‫األحســاء برقــم ‪ 341125336‬وتاريــخ ‪1434/9/7‬ه املرفــق بهــا الصــك‬\n      ‫الصــادر مــن فضيلــة القاضــي بهــا الشــيخ (‪ )........‬املســجل برقــم‬\n      ‫‪ 34176732‬وتاريــخ ‪1434/4/1‬ه اخلــاص بدعــوى (‪ )........‬ضــد (‪)........‬‬\n      ‫يف قضيــة املطالبــة بــأرش نقــص األرض وباالطــاع علــى مــا أجــاب‬\n      ‫بــه فضيلــة القاضــي وأحلقــه بالصــك جواب ـ ًا علــى قرارنــا الســابق رقــم‬\n      ‫‪/34249168‬ش‪/2‬ب يف ‪1434/6/24‬ه ـ قررنــا املصادقــة علــى حكــم‬\n      ‫فضيلتــه واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وآلــه وصحبــه وســلم‬\n                                                          ‫حــرر يف ‪1435/1/16‬ه ـ ‪.‬‬\n\n\n\n\n‫‪293‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"17250706-b6cd-5618-b1f0-019e3dec82ff","source_page_start":287,"source_page_end":293,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"214975726f7c4723c0c7c75414789bec2518a12fede4b17008c9dadad8275537","normalized_text_hash":"1de30ea21bdff9141a194d07cdc05e4cbf382a7cc15e60c1b4be159096b0ed40","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v1-p287-34176732"},{"id":"c0e3c241-91d3-5c6b-86e6-f74174518298","document_type":"judgment","category":"judicial","subcategory":"general","title":"بيع -بيع سيارة -رد ثمن املبيع لعيب -تقدير العيب عن طريق قسم اخلبراء -البينة بحلف اليمن بعد معرفة العيب -احلكم غيابي برد قيمة املبيع املعيب -الغائب على حجيته متى حضر - مت تنفيذ احلكم .","document_number":"34272142","case_number":"32348866","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة مبحافظة جدة بن","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/7/18","year":"1434","subject":"بيع -بيع سيارة -رد ثمن املبيع لعيب -تقدير العيب عن طريق قسم اخلبراء -البينة بحلف اليمن بعد معرفة العيب -احلكم غيابي برد قيمة املبيع املعيب -الغائب على حجيته متى حضر - مت تنفيذ احلكم .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫تاريخه‪1434/7/18 :‬هـ‬\n                ‫ُ‬                  ‫َر ْق ُم َّ‬\n                     ‫الص ِّك‪34272142 :‬‬\n                    ‫َر ْق ُم الدعوى‪32348866 :‬‬\n    ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n          ‫‪ 34384970‬تاريخه‪1434/12/23 :‬هـ‬\n\n\n‫بيــع ‪ -‬بيــع ســيارة ‪ -‬رد ثمــن املبيــع لعيــب ‪ -‬تقديــر العيــب عــن طريــق‬\n‫قســم اخلبــراء ‪ -‬البينــة بحلــف اليمــن بعــد معرفــة العيــب ‪ -‬احلكــم‬\n‫غيابــي بــرد قيمــة املبيــع املعيــب ‪ -‬الغائــب علــى حجيتــه متــى حضــر ‪-‬‬\n                                                       ‫مت تنفيــذ احلكــم ‪.‬‬\n\n\n\n\n                                ‫‪ .1‬املادة (‪ )55‬من نظام املرافعات الشرعية‪.‬‬\n‫‪ .2‬قــول البهوتــي يف الكشــاف‪« :‬فمــن اشــترى معيبــا لــم يعلــم حــال‬\n‫العقــد عيبــه ثــم علــم بعيبــه فلــه اخليــار ســواء علــم البائــع بعيبــه‬\n‫فكتمــه عــن املشــتري أو لــم يعلــم البائــع بعيبــه أو حــدث بــه أي باملبيــع‬\n‫عيــب بعــد العقــد وقبــل القبــض فيمــا ضمانــه علــى البائــع كمكيــل‬\n‫ومــوزون ومعــدود ومــذروع بيــع بذلــك وكثمــر علــى شــجر ونحــوه‬\n‫كمبيــع بصفــة أو رؤيــة متقدمــة خيــر املشــتري بــن رد اســتدراكا ملــا‬\n‫فاتــه وإزالــة ملــا يلحقــه مــن الضــرر يف بقائــه يف ملكــه ناقصــا عــن حقــه‬\n‫وعليــه أي املشــتري إذا اختــار الــرد مؤنــة رده إلــى البائــع حلديــث «علــى‬\n‫اليــد مــا أخــذت حتــى تؤديــه «وإذا رده أخــذ الثمــن كامــا ألن املشــتري‬\n                    ‫بالفســخ اســتحق اســترجاع جميــع الثمــن» ‪. 446/7‬‬\n\n\n\n\n                                                                                     ‫‪294‬‬\n\f      ‫تقــدم املدعــي بدعــوى ضــد شــركة (‪ )........‬بأنــه اشــترى منهــا ســيارة‬\n      ‫دفــع ثمنهــا كامــا وقــد حــدث بهــا أعطــال كثيــرة يف جوهــر الســيارة‬\n      ‫بعــد اســتالمه لهــا ومكوثهــا لديــه ثالثــة أشــهر وأن الســيارة حــاال لــدى‬\n      ‫الشــركة ولتضــرره مــن ذلــك فقــد طلــب احلكــم علــى املدعــى عليهــا‬\n      ‫بــرد مــا دفعــه مــن ثمنهــا ‪ ،‬أقــر وكيــل الشــركة بشــراء املدعــي الســيارة‬\n      ‫منهــا واســتالم الثمــن وأنــه زار قســم الصيانــة عــدة مــرات مــرة ألجــل‬\n      ‫التكييــف ومــرة ألجــل «اجليــر» ومــرة الرتفــاع احلــرارة ثــم عصــا عجلــة‬\n      ‫القيادة ثم وجود صوت ومت إصالح كل ما تقدم وتغيير القطع الالزمة‬\n      ‫بالضمــان وأن الســيارة حــا ًال جاهــزة لالســتعمال ‪ ،‬جــرت الكتابــة‬\n      ‫ألهــل اخلبــرة فعــادت اإلفــادة مــن رئيــس طائفــة صيانــة الســيارات بأنــه‬\n      ‫وبعــد الكشــف اتضــح أنــه لــم يتــم تشــغيل وإصــاح الســيارة بالشــكل‬\n      ‫الصحيــح مــن قبــل الشــركة لذلــك ال ميكــن الكشــف علــى احملــرك‬\n      ‫وال اجلربوكــس وال األنــوار ألنــه يوجــد مشــكلة يف كهربــاء املكينــة‬\n      ‫واجلربوكــس واألنــوار وال ميكــن الكشــف علــى األعطــال إال بعــد‬\n      ‫إصــاح الكهربــاء مــن قبــل الشــركة ‪ ،‬لــم حتضــر املدعــى عليهــا‬\n      ‫اجللســات بعدهــا فقــررت الدائــرة الســير يف الدعــوى غيابيــا عمــا‬\n      ‫باملــادة (‪ )55‬مــن نظــام املرافعــات الشــرعية ‪ ،‬طلبــت الدائــرة مــن املدعــي‬\n      ‫اليمــن علــى أنــه لــم يعلــم عــن العيــب الــذي يف الســيارة عنــد شــرائها مــن‬\n      ‫املدعــى عليهــا فحلــف علــى ذلــك ‪ ،‬وعليــه لوجــود عيــب مؤثــر يف الســيارة‬\n      ‫املشــتراة ولعــدم علمــه بهــذا العيــب ‪ ،‬وألن املدعــى عليهــا وكالــة قــد‬\n      ‫أجابــت بجــواب غيــر مــاق وملــا ورد مــن اخلبيــر مــن عــدم قيــام الشــركة‬\n\n‫‪295‬‬\n\f‫بتشــغيل الســيارة بالشــكل الصحيــح‪ ،‬وألن مــن املتقــرر شــرعا أن مــن‬\n‫اشــترى معيبــا لــم يعلــم بعيبــه إال بعــد العقــد فلــه اخليــار بــن رد املبيــع‬\n‫واســتالم الثمــن أو إمســاك املبيــع مــع األرش‪ .‬صــدر احلكــم علــى‬\n‫الشــركة املدعــى عليهــا بــأن تــرد للمدعــي مــا دفعــه مــن ثمــن ‪ ،‬الغائــب‬\n‫علــى حجتــه متــى حضــر ‪ ،‬صــدق احلكــم مــن محكمــة االســتئناف ‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا (‪ )....‬القاضــي يف احملكمــة العامــة‬\n‫مبحافظــة جــدة بنــاء علــى االســتدعاء احملــال لنــا مــن فضيلــة رئيــس‬\n‫احملكمــة العامــة مبحافظــة جدة‪/‬املســاعد برقــم ‪ 32348866‬وتاريــخ‬\n‫‪1432/08/15‬ه ـ املقيــد باحملكمــة برقــم ‪ 321046966‬وتاريــخ‬\n‫‪1432/08/15‬ه ـ ففــي يــوم االثنــن املوافــق ‪1432/09/01‬ه ـ افتتحــت‬\n‫اجللســة وفيهــا حضــر املدعــي أصالــة (‪ )........‬ولــم يحضــر املدعــى عليــه‬\n‫وال مــن ميثلــه بوكالــة شــرعية بالرغــم مــن تبلغهــم باملوعــد حســب مــا‬\n‫يظهــر مــن أوراق املعاملــة‪ ،‬عليــه فقــد تقــرر رفــع اجللســة وتأجيلهــا إلــى‬\n‫يــوم االثنــن املوافــق ‪1432/12/25‬ه ـ الســاعة احلاديــة عشــر وأقفلــت‬\n‫اجللســة الســاعة احلاديــة عشــر وخمســة وأربعــن دقيقــة وبــاهلل التوفيــق‬\n‫ثــم بتاريــخ ‪1432/12/25‬ه ـ افتتحــت اجللســة وفيهــا حضــر املدعــي‬\n‫أصالــة (‪ )........‬ولــم يحضــر املدعــى عليــه وال مــن ميثلــه بوكالــة شــرعية‬\n‫بالرغــم مــن تبلــغ مستشــار املبيعــات يف الشــركة املدعــى عليهــا حســب‬\n‫مــا يظهــر مــن أوراق املعاملــة ‪ ،‬عليــه فقــد تقــرر رفــع اجللســة وتأجيلهــا‬\n‫إلــى يــوم الســبت املوافــق ‪1433/04/03‬ه ـ الســاعة احلاديــة عشــر وبــاهلل‬\n\n                                                                                        ‫‪296‬‬\n\f      ‫التوفيــق ثــم بتاريــخ ‪1433/04/03‬ه ـ افتتحــت اجللســة وفيهــا حضــر‬\n      ‫املدعــي أصالــة (‪ )........‬وحضــر حلضــوره املدعــى عليــه وكالــة (‪، )........‬‬\n      ‫ســعودي اجلنســية مبوجب الســجل املدني رقم (‪ )........‬الوكيل الشــرعي‬\n      ‫عــن (‪ )........‬بصفتــه وكيــا عــن الشــركاء يف الشــركة (‪ )........‬ذات‬\n      ‫الســجل التجــاري رقــم (‪ )........‬وتاريــخ ‪1426/4/7‬ه ـ مبوجــب الوكالــة‬\n      ‫الصــادرة مــن كاتــب عــدل يف وزارة التجــارة والصناعــة برقــم ‪7267‬‬\n      ‫وتاريــخ ‪1432/12/26‬ه ـ واملخــول لــه فيهــا باملرافعــة واملدافعــة وقبــول‬\n      ‫األحــكام واالعتــراض عليهــا وبســؤال املدعــي وكالــة عــن دعــواه‬\n      ‫أجــاب قائــا لقــد اشــتريت ســيارة مــن نــوع (‪ )........‬موديــل (‪ )........‬مببلــغ‬\n      ‫إجمالــي قــدره إحــدى وأربعــون ألــف ريــال دفعتــه بالكامــل للمدعــى‬\n      ‫عليهــا وقــد حــدث فيهــا أعطــال كثيرة يف جوهر الســيارة بعد اســتالمي‬\n      ‫لهــا ومكوثهــا معــي ملــدة ثالثــة أشــهر والســيارة عنــد الشــركة املدعــى‬\n      ‫عليهــا وقــد تضــررت مــن ذلــك أطلــب احلكــم بــرد مــا دفعتــه قيمــة هــذه‬\n      ‫الســيارة هــذه دعــواي وبســؤال املدعــى عليــه وكالــة عمــا جــاء يف دعــوى‬\n      ‫املدعــي أبــرز مــن يــده مذكــرة جــاء فيهــا (ردا علــى الشــكوى املقامــة‬\n      ‫ضدنــا مــن الســيد (‪ )........‬نفيدكــم بــأن املذكــور قــد اشــترى ســيارة‬\n      ‫مــن الشــركة (‪ )........‬مــن نــوع (‪ )........‬موديــل (‪ )........‬ومت تســجيلها يف‬\n      ‫‪2008/09/20‬م ويف تاريــخ ‪2009/3/6‬م قــام املذكــور بزيــارة قســم‬\n      ‫الصيانــة وكانــت املشــكلة بــأن املكيــف ال يبــرد ومت تغييــر الرديتــر‬\n      ‫حتــت الضمــان وبعدهــا قــام املذكــور بزيــارة الصيانــة يف تاريــخ‬\n      ‫‪2009/12/15‬م وذكــر بــأن هنــاك مشــكلة يف اجليــر بكــس بأنــه ال‬\n      ‫يغيــر ومت حــل املشــكلة وبعــد ذلــك قــام املذكــور بإحضــار الســيارة‬\n      ‫لقســم الصيانة وكانت املشــكلة يف عصى الدركســون ومت تركيبها‬\n\n\n‫‪297‬‬\n\f‫وبعــد أربعــة أيــام قــام املذكــور بإرجــاع الســيارة لقســم الصيانــة بســبب‬\n‫ارتفــاع حــرارة احملــرك وبعــد الكشــف علــى الســيارة اتضــح بــأن مروحة‬\n‫الرديتــر ال تعمــل ومت إصالحهــا وعنــد تشــغل الســيارة كان هناك صوت‬\n‫مرتفــع مــن احملــرك واتضــح بــأن مشــكلة الصــوت تســتوجب تغييــر‬\n‫رأس الســلندر ومت تغييــر القطعــة حتــت الضمــان يف تاريــخ ‪2011/6/7‬م‬\n‫ومت تشــغيل احملــرك والســيارة اآلن جاهــزة للتســليم) عليــه فقــد تقــرر‬\n‫الكتابــة إلــى قســم اخلبــراء يف هــذه احملكمــة لنــدب مــن يلــزم للوقــوف‬\n‫علــى الســيارة املذكــورة والكشــف عليهــا واإلفــادة عــن ذلــك وحتــى‬\n‫ورود اجلــواب فقــد تقــرر رفــع اجللســة وأقفلــت الســاعة احلاديــة عشــر‬\n‫والنصــف وبــاهلل التوفيــق ثــم بتاريخ‪1433/09/10‬ه ـ افتتحــت اجللســة‬\n‫وفيهــا حضــر املدعــي أصالــة (‪ )........‬ولــم يحضــر املدعــى عليــه وال مــن‬\n‫ميثلــه بوكالــة شــرعية بالرغــم مــن تبلــغ املدعــو (‪ )........‬بصفتــه مديــرا‬\n‫للشــركة املدعــى عليهــا حســب مــا يظهر مــن أوراق املعاملة ‪ .‬وقد وردتنا‬\n‫املعاملــة مــن قســم اخلبــراء يف هــذه احملكمــة مبوجــب خطابهــم رقــم‬\n‫‪ 1046966‬وتاريــخ ‪1433/5/18‬ه والــذي جــاء فيــه‪ :‬نعيــد لفضيلتكــم‬\n‫األوراق الــواردة بخطــاب فضيلــة القاضــي (‪ )........‬رقــم ‪33/1046966‬‬\n‫وتاريــخ ‪1433/04/25‬ه ـ بشــأن دعــوى (‪ )........‬ضــد الشــركة (‪)........‬‬\n‫للســيارات واملرفــق بــه التقريــر الــوارد مــن رئيــس طائفــة صيانــة‬\n‫الســيارات ذي الرقــم ‪/279‬ش وتاريــخ ‪1433/05/15‬ه ـ ‪ .‬واملتضمــن‬\n‫( أنــه بعــد الكشــف اتضــح أنــه لــم يتــم تشــغيل وإصــاح الســيارة‬\n‫بالشــكل الصحيــح مــن قبــل الشــركة لذلــك ال ميكــن الكشــف علــى‬\n‫املكينــة وال اجلربوكــس وال األنــوار ألنــه يوجــد مشــكلة يف كهربــاء‬\n‫املكينــة واجلربوكــس واألنــوار وال ميكــن الكشــف علــى األعطــال إال‬\n\n\n                                                                                    ‫‪298‬‬\n\f      ‫بعــد إصــاح الكهربــاء مــن قبــل الشــركة ) اه ـ ‪ ،‬عليــه فقــد تقــرر‬\n      ‫رفــع اجللســة إلبــاغ الشــركة املدعــى عليهــا باحلضــور لدينــا يف اجللســة‬\n      ‫املقــررة يف يــوم األحــد املوافــق ‪1434/02/17‬ه ـ الســاعة العاشــرة‬\n      ‫وأقفلــت اجللســة الســاعة الواحــدة وعشــر دقائــق وبــاهلل التوفيــق ثــم‬\n      ‫بتاريــخ ‪1434/02/17‬ه ـ افتتحــت اجللســة وفيهــا حضــر املدعــي (‪)........‬‬\n      ‫ولــم حتضــر الشــركة املدعــى عليهــا الشــركة (‪ )........‬للســيارات وال‬\n      ‫مــن ميثلهــا بوكالــة شــرعية وقــد وردنــا مــن محضــري اخلصــوم يف هــذه‬\n      ‫احملكمــة مــا يفيــد تبلــغ املدعو (‪ )........‬بصفته مشــرف األمن والســامة‬\n      ‫بالشــركة املدعــى عليهــا ‪ ،‬عليــه فقــد تقــرر رفــع اجللســة وتأجلــت إلــى‬\n      ‫يــوم الســبت املوافــق ‪1434/7/8‬ه ـ الســاعة ‪ 09 : 30‬وبــاهلل التوفيــق ثــم‬\n      ‫بتاريــخ ‪1434/07/08‬ه ـ افتتحــت اجللســة وفيهــا حضــر املدعــي (‪)........‬‬\n      ‫ولــم حتضــر املدعــى عليهــا الشــركة (‪ )........‬للســيارات وال مــن ميثلهــا‬\n      ‫بوكالــة شــرعية وقــد وردت اإلفــادة مــن محضــري اخلصــوم يف هــذه‬\n      ‫احملكمــة متضمنــة التالــي (بعــد الوصــول إلــى املوقع حيث أفاد شــخص‬\n      ‫يعمــل يف نفــس املــكان للشــركة ســابق ًا وقــال إن الشــركة نقلــت مــن‬\n      ‫هنــا) وحيــث إن الشــركة قــد تبلغــت للحضــور لدينــا يف جلســات عــدة‬\n      ‫ولكنهــا لــم حتضــر حســب مــا هــو مــدون يف ضبــط القضية مما اســتلزم‬\n      ‫مواصلــة النظــر يف القضيــة غيابيـ ًا عمــا باملــادة اخلامســة واخلمســن مــن‬\n      ‫نظــام املرافعــات الشــرعية وبســؤال املدعــي وهــل كان يعلــم عــن العيــب‬\n      ‫الواقــع يف الســيارة عنــد شــراءه لهــا فأجــاب قائــا لــم أكــن أعلــم عــن‬\n      ‫وجــود العيــب يف الســيارة عنــد شــرائي لهــا وبســؤاله وهــل لديــه اســتعداد‬\n      ‫علــى أداء اليمــن الالزمــة علــى ذلــك فأجــاب قائــا نعــم لــدي اســتعداد‬\n      ‫بذلــك وقــد أبــرز املدعــي مــن يــده برنــت فيــه معلومــات عــن الســيارة‬\n\n\n‫‪299‬‬\n\f‫الــواردة يف الدعــوى أعــاه وبعــد االطــاع عليهــا وجــد أنهــا مطابقــة‬\n‫للســيارة املوصوفــة يف الدعــوى وقــد ذكــر أن ســنة إنتــاج الســيارة هــو‬\n‫عــام (‪ )........‬وقــد جــرى إرفــاق صــورة مــن هــذا البرنــت يف املعاملــة ‪،‬‬\n‫عليــه فقــد جــرى رفــع اجللســة ملزيــد مــن التأمــل ملــا جــاء فيهــا وتأجلــت‬\n‫إلــى يــوم املوافــق الثالثــاء املوافــق ‪1434/07/18‬ه ـ الســاعة ‪09 : 15‬‬\n‫وبــاهلل التوفيــق ثــم بتاريــخ ‪1434/07/18‬ه ـ افتتحــت اجللســة وفيهــا‬\n‫حضــر املدعــي (‪ )........‬ولــم حتضــر املدعــى عليهــا الشــركة (‪ )........‬وال‬\n‫مــن ميثلهــا بوكالــة شــرعية وبســؤال املدعــي وكالــة وهــل لديــه اســتعداد‬\n‫علــى أداء اليمــن علــى كونــه ال يعلــم بالعيــب الــذي يف الســيارة عنــد‬\n‫شــراءه لهــا مــن املدعــى عليهــا فأجــاب قائــا نعــم لــدي اســتعداد بذلــك‬\n‫فتلفــظ املدعــي يف مجلــس احلكــم قائــا واهلل العظيــم الــذي ال إلــه‬\n‫إال هــو عالــم الغيــب والشــهادة أننــي لــم أكــن أعلــم عــن العيــب الــذي‬\n‫يف الســيارة املوصوفــة أعــاه عنــد شــرائها مــن املدعــى عليهــا الشــركة‬\n‫(‪ )........‬واهلل العظيــم ‪ .‬فبنــاءا علــى مــا تقــدم مــن الدعــوى ومــن إجابــة‬\n‫املدعــى عليهــا وحيــث إن املدعــي يدعــي وجــود عيــب مؤثــر يف الســيارة‬\n‫عنــد شــراءه لهــا لــم ميكنــه مــن االنتفــاع بهــا وعــدم علمــه بهــذا العيــب‬\n‫ومطالبتــه بفســخ البيــع ورد ثمــن املبيــع الــذي دفعــه وحيــث إن املدعــى‬\n‫عليهــا وكالــة قــد أجابــت بجــواب غيــر مــاق حيــث قــد ظهــر مــن‬\n‫البرنــت الــذي تقــدم بــه املدعــي أن املدعــى عليهــا يف جوابهــا لــم تتحــدث‬\n‫عــن ســيارة املدعــي وإمنــا عــن ســيارة أخــرى وذلــك الختــاف ســنة اإلنتــاج‬\n‫اختالف ـ ًا واســع ًا وحيــث إنــه قــد ورد مــن اخلبيــر املتعلــق بالســيارات مــا‬\n‫يفيــد عــدم قيــام الشــركة بتشــغيل الســيارة بالشــكل الصحيــح وحيــث‬\n‫أن املدعــى عليهــا قــد تغيبــت عــن احلضــور بالعــذر الــازم لنظــر هــذه‬\n\n\n                                                                                       ‫‪300‬‬\n\f      ‫القضيــة غيابيــا وحيــث إن املدعــي قــد قــام بــأداء اليمــن الالزمــة علــى‬\n      ‫عــدم علمــه بالعيــب يف الســيارة عنــد شــراءه لهــا وحيــث أن مــن املتقــرر‬\n      ‫شــرعا أن مــن اشــترى معيبــا لــم يعلــم بعيبــه إال بعــد العقــد فلــه اخليــار بــن‬\n      ‫رد املبيــع واســتالم الثمــن أو إمســاك املبيــع مــع األرش قــال يف كشــاف‬\n      ‫القنــاع (فمــن اشــترى معيبــا لــم يعلــم حــال العقــد عيبــه ثــم علــم بعيبــه فلــه‬\n      ‫اخليــار ســواء علــم البائــع بعيبــه فكتمــه عــن املشــتري أو لــم يعلــم البائــع‬\n      ‫بعيبــه أو حــدث بــه أي باملبيــع عيــب بعــد عقــد وقبــل قبــض فيمــا ضمانــه‬\n      ‫علــى بائــع كمكيــل ومــوزون ومعــدود ومــذروع بيــع بذلــك وكثمــر على‬\n      ‫شــجر ونحــوه كمبيــع بصفــة أو رؤيــة متقدمــة خيــر املشــتري بــن رد‬\n      ‫اســتدراكا ملــا فاتــه وإزالــة ملــا يلحقــه مــن الضــرر يف بقائــه يف ملكــه‬\n      ‫ناقصــا عــن حقــه وعليــه أي املشــتري إذا اختــار الــرد مؤنــة رده إلــى‬\n      ‫البائــع حلديــث «علــى اليــد مــا أخــذت حتــى تؤديــه» وإذا رده أخــذ الثمــن‬\n      ‫كامــا ألن املشــتري بالفســخ اســتحق اســترجاع جميــع الثمــن ) ‪446/7‬‬\n      ‫فقــد حكمــت علــى املدعــى عليهــا الشــركة (‪ )........‬بــأن تدفــع لصالــح‬\n      ‫املدعــي (‪ )........‬مبلغــا قــدره واحــد وأربعــون ألــف ريــال قيمــة املبيــع‬\n      ‫املعيــب املوصــوف أعــاه وبعــرض احلكــم علــى املدعــي قــرر قناعتــه بــه‬\n      ‫والغائــب علــى حجتــه متــى حضــر وأمــرت بإصــدار صــك لتبليــغ املدعــى‬\n      ‫عليهــا بنســخة منــه وبــاهلل التوفيــق وصلــى اهلل علــى نبينــا محمــد وعلــى‬\n                                     ‫آلــه وصحبــه وســلم حــرر يف ‪1434/07/18‬ه ـ ‪.‬‬\n      ‫احلمــد هلل وحــده وبعــد فقــد افتتحــت اجللســة وقــد وردتنــا املعاملــة مــن‬\n      ‫محكمــة االســتئناف مبكــة املكرمــة برقــم ‪ 321046966‬وتاريــخ‬\n      ‫‪1435/01/02‬ه ـ واملقيــدة بهــذه احملكمــة برقــم ‪321046966‬وتاريــخ‬\n      ‫‪1435/01/09‬ه ـ واملصدقــة مــن الدائــرة احلقوقيــة اخلامســة مبحكمــة‬\n\n\n‫‪301‬‬\n\f‫االســتئناف مبكــة املكرمــة بالقــرار الصــادر مــن أصحــاب الفضيلــة‬\n‫قضــاة محكمــة االســتئناف رقــم ‪ 34384970‬وتاريــخ ‪1434/12/23‬ه ـ‬\n‫املتضمــن مــا نصــه ‪ :‬وبدراســة احلكــم وصــورة ضبطــه والئحتــه‬\n‫االعتراضيــة تقــررت املوافقــة علــى احلكــم واملدعــى عليهــا علــى حجتهــا‬\n‫إذا حضــرت وبــاهلل التوفيــق ‪ .‬اه ـ ‪ ،‬قاضــي اســتئناف ختــم وتوقيــع‬\n‫(‪ )........‬وقاضــي اســتئناف ختــم وتوقيــع (‪ )........‬ورئيــس الدائــرة ختــم‬\n‫وتوقيــع (‪ ،)........‬عليــه فقــد أمــرت بإحلــاق ذلــك بالضبــط وســجله وبــاهلل‬\n‫التوفيــق وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم حــرر‬\n‫يف ‪1435/01/14‬ه ـ ‪ .‬احلمــد هلل وحــده وبعــد ففــي يــوم األحــد املوافــق‬\n‫‪1435/01/21‬هـ افتتحت اجللســة الســاعة ‪ 11 : 05‬وفيها حضر املدعي‬\n‫(‪ ،)........‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم (‪ )........‬وقــرر‬\n‫قائــا إننــي قــد اســتلمت كامــل املبلــغ احملكــوم لــي بــه أعــاه وقــدر‬\n‫ذلــك واحــد وأربعــون الــف ريــال فقــط ال غيــر مبوجــب الشــيك املســحوب‬\n‫علــى بنــك (‪ )........‬برقــم (‪ )........‬وتاريــخ ‪ 2013/11/19‬وبهــذا لــم تعــد‬\n‫لــي أي مطالبــة أو دعــوى ضــد الشــركة (‪ )........‬بهــذه اخلصــوص عليــه‬\n‫وحيــث احلــال مــا ذكــر فقــد أمــرت بالتهميــش علــى ســجل هــذا الصــك‬\n‫مبــا يفيــد ذلــك وبــاهلل التوفيــق وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه‬\n                                  ‫وصحبــه وســلم حــرر يف ‪1435/1/21‬ه ـ ‪.‬‬\n‫احلمد هلل وحده‪ ،‬والصالة والســام على رســول اهلل ‪ ،‬وبعد‪ :‬فقد جرى‬\n‫م ّنــا نحــن قضــا َة االســتئناف بالدائــرة احلقوقيــة اخلامســة يف محكمــة‬\n‫االســتئناف مبنطقــة مكــة املكرمــة االطــا ُع على هــذا احلكم الصادر‬\n‫مــن فضيلــة الشــيخ (‪ )........‬القاضــي يف احملكمــة العامــة مبحافظــة‬\n‫جــدة املســجل بعــدد ‪ 34272142‬وتاريــخ ‪1434/07/18‬ه ـ املتضمــن‬\n\n\n                                                                                      ‫‪302‬‬\n\f      ‫دعــوى (‪ )........‬ضــد الشــركة (‪ )........‬احملكــوم في ــه مبــا دون باطــن‬\n      ‫الصــك ‪ ،‬وبدراســة احلكــم وص ــورة ضبط ــه والئحتــه االعتراضيــة تقــرر‬\n      ‫املوافقــة علــى احلكــم واملدعــى عليهــا علــى حجتهــا إذا حضــرت وبــاهلل‬\n          ‫التوفيــق ‪،‬وصل ــى اهلل عل ــى نبينــا محمــد وعل ــى آل ــه وصحب ــه وســلم ‪.‬‬\n\n\n\n\n‫‪303‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"17250706-b6cd-5618-b1f0-019e3dec82ff","source_page_start":294,"source_page_end":303,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"bd507f8d592d6ea1887bf052a645697c9390c2da6dabb73c1b22959c5899685f","normalized_text_hash":"8f86bf50a4840e30605a078a2f128dd1a2daada50d6d648d7ec20b6a52172881","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v1-p294-34272142"},{"id":"00dc2012-151f-5db3-9502-788ad39541d4","document_type":"judgment","category":"judicial","subcategory":"general","title":"بيع -طلب فسخ عقد البيع لإلخال ببنوده -تخلف املدعى عليه ال -ال تسمع مين عن احلضور بعد توجيه اليمن عليه يعد ناك املدعى عليه بعد حلف املدعي والقضاء له -ال ميكن اخلصم من أداء اليمن بعد احلكم بنكوله -النماء املنفصل يف وقت اخليار هو للمشتري ألن العن من ضمانه -اخال املدعى عليه ببنود العقد يوجب خيار الفسخ للمدعي -احلكم بفسخ البيع ورد قيمته من املدعى عليه الثاني ورد الدعوى ضد املدعى عليه األول .","document_number":"33364368","case_number":"32380395","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بالرياض","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1433/8/3","year":"1434","subject":"بيع -طلب فسخ عقد البيع لإلخال ببنوده -تخلف املدعى عليه ال -ال تسمع مين عن احلضور بعد توجيه اليمن عليه يعد ناك املدعى عليه بعد حلف املدعي والقضاء له -ال ميكن اخلصم من أداء اليمن بعد احلكم بنكوله -النماء املنفصل يف وقت اخليار هو للمشتري ألن العن من ضمانه -اخال املدعى عليه ببنود العقد يوجب خيار الفسخ للمدعي -احلكم بفسخ البيع ورد قيمته من املدعى عليه الثاني ورد الدعوى ضد املدعى عليه األول .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫تاريخه‪1433/8/3 :‬هـ‬\n               ‫ُ‬                  ‫َر ْق ُم َّ‬\n                    ‫الص ِّك‪33364368 :‬‬\n                   ‫َر ْق ُم الدعوى‪32380395 :‬‬\n   ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n          ‫‪ 34197033‬تاريخه‪1434/4/24 :‬هـ‬\n\n\n‫بيــع ‪ -‬طلــب فســخ عقــد البيــع لإلخــال ببنــوده ‪ -‬تخلــف املدعــى عليــه‬\n‫ال ‪ -‬ال تســمع ميــن‬ ‫عــن احلضــور بعــد توجيــه اليمــن عليــه يعــد نــاك ً‬\n‫املدعــى عليــه بعــد حلــف املدعــي والقضــاء لــه ‪ -‬ال ميكــن اخلصــم مــن‬\n‫أداء اليمــن بعــد احلكــم بنكولــه ‪ -‬النمــاء املنفصــل يف وقــت اخليــار هــو‬\n‫للمشــتري ألن العــن مــن ضمانــه ‪ -‬اخــال املدعــى عليــه ببنــود العقــد‬\n‫يوجــب خيــار الفســخ للمدعــي ‪ -‬احلكــم بفســخ البيــع ورد قيمتــه مــن‬\n             ‫املدعــى عليــه الثانــي ورد الدعــوى ضــد املدعــى عليــه األول ‪.‬‬\n\n\n\n\n‫‪ .1‬جــاء يف املغنــي ‪« 235/14‬وأمــا إذا حلــف أي املدعــي وقضــي لــه فعــاد‬\n‫املدعــى عليــه وبــذل اليمــن لــم يســمع منــه وهكــذا لــو بذلهــا بعد احلكم‬\n‫عليــه بنكولــه لــم يســمع ألن احلكــم قــد مت فــا ينقــض كمــا لــو قامــت‬\n                                                                       ‫بينة»‪.‬‬\n‫‪ .2‬جــاء يف املغنــي ‪( :‬ومــا يحصــل مــن غــات املبيــع ومنائــه املنفصــل يف‬\n‫مــدة اخليــار فهــو للمشــتري أمضيــا العقــد أم فســخاه )‪..‬إلــى أن قــال‪:‬‬\n‫(ولنــا قــول النبــي صلــى اهلل عليــه وســلم ‪« :‬اخلــراج بالضمــان» قــال‬\n‫الترمــذي هــذا حديــث صحيــح ‪ .‬وهــذا مــن ضمــان املشــتري فيجــب أن‬\n‫يكــون خراجــه لــه وألن امللــك ينتقــل بالبيــع علــى مــا ذكرنــا فيجــب‬\n                         ‫أن يكــون منــاؤه لــه كمــا بعــد انقضــاء اخليــار)‪.‬‬\n                                ‫‪ .3‬املادة ‪ 109‬من نظام املرافعات الشرعية ‪.‬‬\n                                                                                  ‫‪304‬‬\n\f      ‫ادعــى املدعــي علــى املدعــى عليــه االول انــه اشــترى منــه مطعــم مببلــغ‬\n      ‫مالــي محــدد دفــع يف العقــد مبوجــب صــورة املســتندات ومت االشــتراط‬\n      ‫يف العقــد انــه يقــوم البائــع بنقــل عــدد ‪ 15‬عامــل مــن عمــال املطعــم وعــدد‬\n      ‫(‪ )10‬تأشــيرات إلــى دولــة تركيــا ‪ ،‬وكذلــك يتعهد البائع بنقل الســجل‬\n      ‫التجــاري كمســتثمر اجنبــي ‪ ،‬أقــر املدعــى عليــه بذلــك مبوجــب صــك‬\n      ‫احلكــم الصــادر مــن احملكمــة العامــة بالريــاض ‪ ،‬وحيــث إن املطعــم‬\n      ‫عائــد الســجل التجــاري إلــى املدعــى عليــه الثانــي وانــه احــال ثمــن املبيــع‬\n      ‫إليــه كديــن لــه يف ذمــة املدعــى عليــه الثانــي ومت دفعــه للمدعــى عليــه‬\n                  ‫األول ورغــم ذلــك لــم يلتــزم املدعــى عليــه الثانــي ببنــود العقــد ‪.‬‬\n      ‫وبنــاء علــى مــا تقــدم وإلخــال املدعــى عليــه ببنــود العقــد طلــب املدعــي‬\n      ‫فســخ العقــد وإعــادة املبلــغ واحلكــم بالتعويــض عــن الضــرر احلاصــل مــن‬\n                                     ‫تاريــخ اســتالم إلــى تاريــخ الفصــل يف الدعــوى ‪.‬‬\n      ‫دفــع املدعــى عليــه بعــدم اخاللــه بالعقــد وأنــه اســتلم جــزء مــن املبلــغ‬\n      ‫وتبقــى جــزء حلــن اســتكمال كافــة اإلجــراءات من نقل كفالــة للعمال‬\n      ‫والســجل التجــاري وســداد بعــض املصروفــات ‪ ،‬ومت عقــد جلســة تصفيــة‬\n      ‫وتبــن أن املدعــي مديــن مببلــغ قــدره ‪ ....‬تدفــع حني اســتخراج ‪ 25‬تأشــيرة‬\n      ‫حســب االتفــاق ‪ ،‬ذكــر املدعــى عليــه ان التأخيــر بســبب املدعــي لعــدم‬\n                  ‫قيامــه بإنهــاء االجــراءات املتعلقــه بالســجل التجــاري للمؤسســة‬\n      ‫انكــر املدعــي وكالــة ذلــك ‪ ،‬وطلــب ميــن املدعــى عليــه علــى نفــي‬\n      ‫ذلــك‪ ،‬لــم يحضــر املدعــى عليــه ولكونــه تخلــف مت اعتبــاره نــاكال عــن‬\n                ‫اليمــن اســتنادا للمــادة (‪ )109‬مــن نظــام املرافعــات الشــرعية ‪.‬‬\n\n‫‪305‬‬\n\f            ‫ردت اليمني على املدعي فحلف انه سلم كامل قيمة املطعم ‪.‬‬\n‫وحيــث أقــر املدعــى عليــه الثانــي ببيعــه املطعــم بالقيمــة املذكــورة وأقــر‬\n‫بــأن املدعــي عليــه االول مجــرد وســيط وأقــر بــأن مــن ضمــن االتفــاق‬\n‫تســليم التأشــيرات للعمــال وإلقــرار املدعــى عليــه الثانــي أن االتفــاق بــن‬\n‫الطرفــن كان علــى اســاس ان يتــم ادخــال املدعــى يف الســجل التجــاري‬\n‫اخلــاص باملدعــى عليــه الثانــي أو اخلــاص بوالــد املدعــى عليــه كمســتثمر‬\n‫‪ .‬ولكــون املدعــى عليــه ‪ ...‬أقــر بــأن ذلــك لــم يتــم ودفــع بــأن ســبب ذلــك‬\n‫تأخــر املدعــي يف اإلجــراءات وال بينــه للمدعــى عليــه علــى ذلــك ‪،‬‬\n‫ولنكــول املدعــى عليــه الثانــي عــن أداء اليمــن وحللــف املدعــي اليمــن ‪،‬‬\n‫ولعــدم وجاهــة ماطلبــه املدعــى مــن اخلســارة لعــدم وجــود ســبب مباشــر‬\n‫مــن املدعــى عليــه ‪ ،‬صــدر احلكــم بفســخ العقــد الــذي بــن املدعــي‬\n‫واملدعــى عليــه الثانــي بخصــوص بيــع املطعــم ‪ ،‬وإلــزام املدعــى عليــه‬\n‫الثانــي بإعــادة قيمتــه للمدعــي ‪ ،‬ورد دعــوى املدعــي ضــد املدعــى عليــه‬\n‫األول ‪ ،‬وصــرف النظــر عــن دعــوى املدعــي فيمــا زاد علــى ماحكــم بــه‪،‬‬\n                                  ‫صــدق احلكــم مــن محكمــة االســتئناف ‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده ‪ ،‬وبعــد ‪ ،‬فلــدي أنــا (‪ )....‬القاضــي باحملكمــة العامــة‬\n‫وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة العامــة‬\n‫برقــم ‪ 32380395‬وتاريــخ ‪1432/08/01‬ه ـ واملقيــدة برقــم ‪32967570‬‬\n‫وتاريــخ ‪1432/08/01‬ه ـ حضــر ‪...‬تركــي اجلنســية مبوجــب رخصــة‬\n‫اإلقامــة رقــم ‪...‬كمــا حضــر ‪...‬ســعودي بالســجل املدنــي رقــم ‪...‬مبوجــب‬\n\n                                                                                      ‫‪306‬‬\n\f      ‫الوكالــة رقــم ‪ 49533‬وتاريــخ ‪1430/6/23‬هـ واملخول له فيها باملطالبة‬\n      ‫واملرافعــة واملخاصمــة وإقامــة الدعــاوى واإلقــرار واإلنــكار والصلــح‬\n      ‫وقبــول احلكــم واالعتــراض عليــه وحضــر حلضــوره ‪...‬تركــي اجلنســية‬\n      ‫رقــم اإلقامــة ‪ ...‬كمــا حضــر ‪...‬تركــي اجلنســية مبوجــب رخصــة اإلقامــة‬\n      ‫رقــم ‪...‬وادعــى األول قائــا ‪ :‬باعنــي املدعــى عليــه األول املطعــم املســمى‪...‬‬\n      ‫الكائــن موقعــة بحــي ‪ ...‬بالريــاض مببلــغ وقــدره مليــون ومائــة وعشــرون‬\n      ‫ألــف ريــال اســتلمها املذكــور مبوجــب صــورة الســندات املرفقــة ومت‬\n      ‫االشــتراط يف عقــد البيــع ومجلــس العقــد أن يقــوم بنقــل كفالــة عــدد‬\n      ‫(‪ )15‬عامــل مــن عمــال املطعــم املبــاع وأن يعطينــي عــدد (‪ )10‬تأشــيرات‬\n      ‫إلــى دولــة تركيــا وأن يقــوم املدعــى عليــه بنقــل الســجل التجــاري للمبــاع‬\n      ‫إلــى اســمي كمســتثمر أجنبــي وقــد أقــر املدعــى عليــه األول بذلــك‬\n      ‫مبوجــب صــك احلكــم بتاريــخ ‪1431/11/22‬ه ـ الصــادر مــن احملكمــة‬\n      ‫العامــة بالريــاض املرفــق صورتــه وحيــث إن املدعــى عليــه األول دفــع بــأن‬\n      ‫املطعــم عائــد ســجله التجــاري إلــى املدعــى عليــه الثانــي وانــه أحــال ثمــن‬\n      ‫املبيــع إليــه حيــث إن املدعــى عليــه الثانــي عليــه ديــن لــأول وأحــال الثمــن‬\n      ‫الــذي دفعتــه أنــا املشــتري إلــى األول بقولــه ذلــك أمــام فضيلــة ناظــر‬\n      ‫الدعــوى وقــد اســتلم منــي املدعــى عليــه األول العــوض كامــا املبلــغ‬\n      ‫املنــوه عنــه وحيــث إنــه مت االشــتراط يف عقــد البيــع ومجلــس العقــد بــأن‬\n      ‫يلتــزم البائــع بالشــروط املذكــور أعــاه فإنــه حتــى تاريخــه لــم يلتــزم بهــا‬\n      ‫وحيــث إن قيمــة املبــاع دون حتقيــق تلــك الشــروط يســاوي ثمن ـ ًا قــدره‬\n      ‫مائتــا ألــف ريــال فقــط وحيــث أنــه منــذ تاريــخ اســتالمي للمطعــم يف‬\n      ‫‪1430/7/1‬ه ـ بحالتــه املخالفــة لشــروط البيــع فإننــي تعرضــت خلســارة‬\n      ‫شــهرية قدرهــا خمســة آالف ريــال ألن األربــاح الشــهرية للمطعــم يف حالــة‬\n\n\n‫‪307‬‬\n\f‫التــزام املدعــى عليهمــا بعقــد البيــع تســاوي أربعــن ألــف ريــال وأطلــب‬\n‫فســخ العقــد واحلكــم بإعــادة املبلــغ واحلكــم لــي بالتعويــض عــن الضــرر‬\n‫احلاصــل لــي تقــدر مــن تاريــخ اســتالمي للمطعــم حتــى تاريــخ الفصــل يف‬\n‫هــذه الدعــوى واخلســارة شــهريا تقــدر بخمســة آالف ريــال هــذه دعــواي ‪،‬‬\n‫وبســؤال املدعــى عليــه ‪...‬عــن جوابــه علــى دعــوى املدعــي أبــرز إجابــة‬\n‫محــررة جــاء فيهــا «حيــث إن العقــد عقــد صحيــح مســتوف للشــروط‬\n‫ملــزم لكافــة األطــراف فــا يحــق للمدعــي فســخه ألننــا لــم نخــل بــأي‬\n‫مــن شــروط االتفــاق وألننــا قمنــا بنقــل الســجل التجــاري لــه لــدي اجلهــات‬\n‫املختصــة ونوضــح لفضيلتكــم أن الســيد ‪...‬تركــي اجلنســية كان‬\n‫وســيط ًا ال ناقــة لــه بهــا وال جمــل وال ميثــل البائــع وال املشــتري وليــس‬\n‫مفوضـ ًا مــن أي طــرف مــن األطــراف وبالنســبة لطلبــه الثانــي إعــادة مبلــغ‬\n‫البيــع فقــد اســتلمت منــه مبلــغ (‪ )920.000‬تســعمائة وعشــرون ألــف‬\n‫ريــال عــن طريــق ‪...‬مــن أصــل مبلــغ ( ‪ )1.120.000‬مليون ومائة وعشــرين‬\n‫ألــف ريــال وتبقــي لــي مبلــغ (‪ )200000‬مائتــا ألــف ريــال تركتهــا يف‬\n‫ذمتهــم إلنهــاء إجــراءات نقــل كفالــة العمــال والســجل التجــاري وســداد‬\n‫بعــض املصروفــات وقيمــة التأشــيرات التــي وعدتهــم بهــا وبعــد ســنة‬\n‫ونصــف مــن تاريــخ املبايعــة واســتالمهم املطعــم عقدنــا جلســة مــع املدعــي‬\n‫عليــه وقمنــا بعمــل تصفيــة حســابات معــه وتبــن أن لــي بذمتــه مبلــغ‬\n‫(‪ )110000‬مائــة وعشــرة آالف ريــال وكان متبقــي نقــل كفالــة العمــال‬\n‫واســتخراج التأشــيرات وحســب االتفــاق أن هــذا املبلــغ املتبقــي يدفــع لــي‬\n‫يف حالــة إنهــاء اســتخراج (‪ )25‬تأشــيرة مــن اجلنســية التركيــة الــذي‬\n‫قمنــا باالتفــاق معــه بــدال عــن نقــل كفالــة العمــال مــن اجلنســية‬\n‫البنجالدشــية وذلــك لصــدور قــرار مينــع نقــل كفالــة املذكوريــن مــع‬\n\n\n                                                                                     ‫‪308‬‬\n\f      ‫العلــم أننــا قمنــا بتســليمه تنــازل لكافــة العمالــة اخلاصــة باملطعــم فــور‬\n      ‫تنازلنــا عــن الســجل التجــاري ولــم يلتــزم بنقــل كفالــة ممــا اضطرنــا‬\n      ‫للتبليــغ عنهــم لــدى إدارة الوافديــن مبنطقــة الريــاض عــن تغيبهــم وذلــك‬\n      ‫إلخــاء املســؤولية ويف حــال لــم ينههــا يعتبــر غيــر قابــل للدفــع وال يحــق‬\n      ‫لــه املطالبــة بــه وبالنســبة لطلبــه رقــم (‪ )3‬يف صحيفــة الدعــوي حســب مــا‬\n      ‫جــاء بهــا أن دخــل املطعــم قبل أن يشــتريه املدعــي كان (‪ )40000‬أربعني‬\n      ‫ألــف ريــال وذلــك يــدل علــى أن اخلســائر وردت بعــد اســتالمه املطعــم‬\n      ‫لســوء إدارته»إ‪.‬ه ـ ‪ ،‬ثــم قــرر املدعــى عليــه ‪ ...‬أنــه بقــي لــه يف ذمــة املدعــي‬\n      ‫مــن قيمــة املطعــم مائــة ألــف ريــال لــم يســتلمها وبالرجــوع للمفاهمــة‬\n      ‫النهائيــة بــن الطرفــن حســب مــا ذكــراه أنهــا نهائيــة وهــي صــادرة مــن‬\n      ‫مكتــب ‪...‬للترجمــة املعتمــدة ونصهــا «أنــا ‪...‬وعــدت ‪...‬بإعطــاء عــدد ‪25‬‬\n      ‫تأشــيرة إثــر بيعــي عليهــم مطعمــي وإدخــال ‪...‬و‪...‬والدهــم ‪...‬يف رخصــة‬\n      ‫االســتثمار اخلاصــة بــي وحيــث أنــا مكلــف بذلــك ســوف أســتلم مبلــغ‬\n      ‫وقــدره مائــة وعشــرة آالف ريــال ســعودي بعــد إكمــال اإلجــراءات‬\n      ‫وأســتلم املبلــغ الباقــي املســتحق أتعهــد بتســليم التأشــيرات والســجل‬\n      ‫خــال ‪ 45‬يومــا وتكــون التأشــيرات علــى ســجل ‪...‬الواعــد ‪ ...‬توقيعــه‬\n      ‫‪...‬توقيعــه الشــاهد ‪...‬توقيعــه والشــاهد الثانــي ‪...‬توقيعه»إ‪.‬ه ـ ‪ ،‬وقــد أقــرا‬\n      ‫بصحتهــا عنــدي يف اجللســة وبســؤال املدعــى عليــه ‪...‬هــل اســتخرجت‬\n      ‫التأشــيرات فأجــاب بقولــه ‪ :‬وجــدت مشــكلة وهــي أن مكتــب العمــل‬\n      ‫يطالــب بشــهادة علــى الســعودة ولــم تكــن ‪...‬لديــه شــهادة وكذلــك ال بــد‬\n      ‫مــن شــهادة علــى الــزكاة والتأمينــات وكان الســجل ‪...‬باســم والــد‬\n      ‫املدعــي ولــم يكــن موجــودا يف اململكــة فلمــا مضــت مــدة خمســة‬\n      ‫وأربعــن يومــا أصبحــت غيــر مســؤول عنهــم هكــذا أجــاب وبعــرض‬\n\n\n‫‪309‬‬\n\f‫ذلــك علــى املدعــي أجــاب بقولــه صحيــح أن والــدي كان غيــر متواجــد‬\n‫يف الســعودية إال أن لــه وكيــا يســتطيع أن يجــدد الســجل وقــد أعطينــا‬\n‫الســجالت لرجــل يدعــى ‪...‬وقــد عرفتــه عــن طريــق املدعــى عليــه ‪...‬وهــو‬\n‫معقــب وســلمت للمعقــب ثالثــن ألــف ريــال عــن ‪...‬علــى أن يخصمهــا مــن‬\n‫املبلــغ املتبقــي مــن قيمــة املطعــم ومكثــت الســجالت عنــد املعقــب ولــم‬\n‫يعطنيهــا إال بعــد ثالثــة أشــهر وقــد رجــع والــدي وبعدهــا خــال أســبوع‬\n‫جددنــا الســجل وكان الســجل يوجــد فيــه إثبــات الســعودة والــزكاة‬\n‫والتأمينــات وأصبــح جاهــزا ولــم يبــق إال أن يأخــذه املدعــى عليــه‪...‬‬\n‫ويســتخرج تأشــيرات ولكنــه لــم يفعــل حتــى اآلن هكــذا أجاب وبعرض‬\n‫ذلــك علــى املدعــى عليــه ‪...‬أجــاب بقولــه ‪ :‬إن جتديــد الســجل لــم يكــن‬\n‫إال بعــد ثالثــة أشــهر وأنــا متعهــد يف اخلمســة واألربعــن يومــا فقــط ومــا‬\n‫بعدهــا فــا عالقــة لــي بــه هكــذا أجــاب ثــم رفعــت اجللســة ألخــذ إجابــة‬\n‫املدعــي علــى مــا دفــع بــه املدعــى عليــه ‪ ،...‬ويف جلســة أخــرى حضــر‬\n‫املدعــي أصالــة كمــا حضــر وكيلــه ‪...‬ســعودي بالســجل املدني رقــم‪......‬‬\n‫مبوجــب الوكالــة الصــادرة مــن عــدل الريــاض الثانيــة برقــم ‪22237‬‬\n‫وتاريــخ ‪1433/03/20‬ه ـ جلــد (‪ )20261‬والتــي تخولــه حــق املرافعــة‬\n‫واملدافعــة واإلقــرار كمــا حضــر ‪...‬ســعودي بالســجل املدنــي رقــم ‪...‬‬\n‫بالوكالــة عــن املدعــى عليــه األول ‪...‬مبوجــب الوكالــة الصــادرة مــن‬\n‫عــدل الريــاض الثانيــة برقــم ‪ 47660‬وتاريــخ ‪1433/06/23‬ه ـ جلــد‬\n‫(‪ )20515‬والتــي تخولــه حــق املرافعــة واملدافعــة واإلقــرار والصلــح‬\n‫وبالوكالــة عــن املدعــى عليــه الثانــي ‪ ...‬مبوجــب الوكالــة الصــادرة مــن‬\n‫عــدل الريــاض الثانيــة برقــم ‪ 55914‬وتاريــخ ‪1432/07/26‬ه ـ جلــد‬\n‫(‪ )19708‬والتــي تخولــه حــق املرافعــة واملدافعــة وبســؤال املدعــي عــن‬\n\n\n                                                                                    ‫‪310‬‬\n\f      ‫جوابــه علــى مــا ذكــره املدعــى عليهمــا يف اجللســة املاضيــة قــال ‪ :‬مــا‬\n      ‫ذكــره مــن أن تأخــره يف إصــدار التأشــيرات ونقــل املطعــم إلــى ســجل‬\n      ‫مطاعــم ‪ ...‬كان بســبب تأخرنــا يف إنهــاء اإلجــراءات املتعلقــة باملؤسســة‬\n      ‫املذكــورة فهــذا غيــر صحيــح والصحيــح أن كامــل األوراق قــد ســلمتها‬\n      ‫للمعقــب املذكــور املدعــو ‪...‬بعلــم املدعــى عليــه الثانــي وهــو يعمــل معقــب‬\n      ‫لديــه بــل ووكيــل عنــه هكــذا قــال فســألت املدعــى عليــه وكالــة هــل‬\n      ‫لــدى موكلــه الثانــي بينــة علــى أن تأخــره يف إصــدار التأشــيرات وعــدم‬\n      ‫نقــل املطعــم للســجل التجــاري املذكــور كان بســبب املدعــي فقــال ‪:‬‬\n      ‫ســوف أراجــع موكلــي وأجيــب يف اجللســة القادمــة ‪ ،‬ويف جلســة أخــرى‬\n      ‫حضــر املدعــي أصالــة واملدعــي وكالــة واملدعــى عليــه وكالــة وبســؤال‬\n      ‫املدعــى عليــه وكالــة عــن جوابــه أبــرز ورقــة تضمنــت جوابــه علــى‬\n      ‫الدعــوى املــدون ســابق ًا ولــم أر مــا يوجــب إعــادة تدوينــه ثــم قــال املدعــي‪:‬‬\n      ‫إن االتفــاق الــذي حصــل بيننــا بخصــوص الســجل التجــاري هــو أن يتــم‬\n      ‫إدخالــي يف الســجل التجــاري اخلــاص باملدعــى عليــه الثانــي كمســتثمر‬\n      ‫أو إدخالــي يف الســجل التجــاري اخلــاص بوالــدي كمســتثمر أيضـ ًا وهذا‬\n      ‫كان أســاس االتفــاق وبعــرض ذلــك علــى املدعــى عليــه وكالــة قــال ‪ :‬مــا‬\n      ‫ذكــره صحيــح ولكــن كان ذلــك كمــا ذكــرت بســبب تأخــر املدعــي‬\n      ‫يف إنهــاء اإلجــراءات اخلاصــة بــه فســألته هــل لديــه بينــة علــى ذلــك فقــال‬\n      ‫‪ :‬أكتفــي مبــا ذكرتــه ســابق ًا فســألته هــل ترغــب يف ميــن املدعــي علــى‬\n      ‫نفــي أن يكــون تأخــر يف إنهــاء اإلجــراءات الالزمــة إلدخالــه كمســتثمر‬\n      ‫يف ســجل املدعــى عليــه الثانــي أو يف ســجل والــده فقــال‪ :‬ال أرغــب يف‬\n      ‫ميينــه ثــم ســألت املدعــي عمــا ذكــره املدعــى عليــه الثانــي يف جوابــه‬\n      ‫ســابق ًا مــن أنــه لــم يســتلم مــن املدعــي ســوى مبلــغ تســعمائة وعشــرين‬\n\n\n‫‪311‬‬\n\f‫ألــف ريــال فقــال ‪ :‬إن املدعــى عليــه الثانــي قــد اســتلم كامــل الثمــن‬\n‫وقــدره مليــون ومائــة وعشــرون ألــف ريــال حيــث ســلمت تســعمائة‬\n‫وعشــرين ألــف ريــال نقــد ًا ومائــة ألــف ريــال ســلمتها مديونية علــى املطعم‬\n‫عبــارة عــن رواتــب ســابقة للعمــال ومبلــغ ســتة وثالثــن ألــف ريــال قيمــة‬\n‫فاتــورة ميــاه وأربعــة وعشــرين ألــف ريــال قيمــة فاتــورة كهربــاء ومبلــغ‬\n‫أربعــن ألــف ريــال ســلمته نقــد ًا أيض ـ ًا هكــذا قــال وبعــرض ذلــك علــى‬\n‫املدعــى عليــه وكالــة قــال ‪ :‬لــم يســتلم موكلــي ‪ ....‬مــن املدعــي ســوى‬\n‫املبلــغ الــذي ذكــر وقــدره تســعمائة وعشــرون ألــف ريــال فســألت املدعي‬\n‫ألديــه بينــة علــى ذلــك فقــال ‪ :‬أنــا أرضــى بيمــن املدعــى عليــه الثانــي‬\n‫علــى أنــه لــم يســتلم تلــك املبالــغ هكــذا قــال وبعــرض ذلــك علــى املدعــى‬\n‫عليــه وكالــة قــال ‪ :‬ســوف أحضــر موكلــي يف اجللســة القادمــة لعــرض‬\n‫ذلــك عليــه ‪ ،‬ويف جلســة أخــرى حضــر املدعــي أصالــة واملدعــي وكالــة‬\n‫ولــم يحضــر املدعــى عليهمــا وال وكيلهمــا رغــم تبلــغ الوكيــل باملوعــد‬\n‫يف اجللســة املاضيــة وحيــث إن هــذه اجللســة هــي لطلــب اليمــن من املدعى‬\n‫ال‬\n‫عليــه الثانــي ولكونــه قــد تخلــف عــن احلضــور لــذا فقــد اعتبرتــه نــاك ً‬\n‫عــن اليمــن اســتناد ًا للمــادة (‪ )109‬مــن نظــام املرافعــات ورددت اليمــن‬\n‫ا «واهلل‬‫علــى املدعــي وبطلــب اليمــن منــه اســتعد بهــا ثــم حلــف قائ ـ ً‬\n‫العظيــم أننــي ســلمت كامــل قيمــة املطعــم وقدرهــا مليــون ومائــة‬\n‫وعشــرون ألــف ريــال حيــث إننــي دفعــت مبلــغ مائــة ألــف ريــال رواتــب‬\n‫للعمــال كانــت مدينــة علــى املطعــم قبــل اســتالمي لــه ودفعــت مبلــغ‬\n‫أربعــة وعشــرين ألــف ريــال فاتــورة كهربــاء ومبلــغ ســتة وثالثــن ألــف‬\n‫ريــال فاتــورة ميــاه كانــت علــى املطعــم قبــل اســتالمي لــه ومبلــغ أربعــن‬\n‫ألــف ريــال ســلمتها نقــد ًا للمدعــى عليــه الثانــي مــن قيمــة املطعــم وكان‬\n\n\n                                                                                     ‫‪312‬‬\n\f      ‫ـاء‬\n      ‫االتفــاق أن أســتلم املطعــم خاليـ ًا مــن أي مديونيــات» هكــذا حلــف فبنـ ً‬\n      ‫علــى مــا تقــدم مــن الدعــوى واإلجابــة وحيــث أقــر املدعــى عليــه الثانــي‬\n      ‫ببيعــه املطعــم املذكــور علــى املدعــي بالقيمــة املذكــورة وأقــر بــأن‬\n      ‫املدعــى عليــه األول مجــرد وســيط وقــد أقــر بــأن مــن ضمــن االتفــاق‬\n      ‫تســليم تأشــيرات العمــال املذكــورة وإلقــرار وكيــل املدعــى عليــه‬\n      ‫الثانــي بــأن االتفــاق بــن الطرفــن كان علــى أســاس أن يتــم إدخــال‬\n      ‫املدعــي يف الســجل التجــاري اخلــاص باملدعــى عليــه الثانــي أو اخلــاص‬\n      ‫بوالــد املدعــي كمســتثمر ولكــون املدعــى عليــه قــد أقــر بــأن ذلــك لــم‬\n      ‫يتــم ودفــع بــأن ذلــك كان بســبب تأخــر املدعــي يف اإلجــراءات وألنــه ال‬\n      ‫بينــة لــه علــى ذلــك ولــم يــرض بيمــن املدعــي علــى نفــي ذلــك وألن ذلــك‬\n      ‫األمــر هــو إخــال مــن جهــة املدعــى عليــه الثانــي ببنــود االتفــاق الــذي بــن‬\n      ‫الطرفــن وهــو يوجــب خيــار الفســخ للمدعــي وألن املدعــي قــد طالــب‬\n      ‫بفســخ العقــد ولكــون املدعــى عليــه الثانــي قــد دفــع بأنــه لــم يســتلم مــن‬\n      ‫القيمــة ســوى املبلــغ الــذي ذكــر ومبــا أن املدعــي لــم يقــم بينــة علــى‬\n      ‫ســداد بقيــة القيمــة التــي ذكــر ورضــي بيمــن املدعــى عليــه الثانــي‬\n      ‫ولكــون املدعــى عليــه الثانــي قــد نــكل عــن أداء اليمــن وحيــث إن‬\n      ‫املدعــي قــد أدى اليمــن علــى الصفــة املوافقــة لدعــواه بعــد ردهــا إليــه‬\n      ‫ونظــر ًا لعــدم وجاهــة مطالبــة املدعــي بخســارة املطعــم بعــد اســتالمه‬\n      ‫نظــر ًا لكــون تلــك اخلســارة لــم تكــن بســبب مباشــر مــن املدعــى عليــه‬\n      ‫الثانــي إذ أن املطعــم كان حتــت اســتالم املدعــي وتصرفــه لــذا فقــد‬\n      ‫قــررت مــا يلــي ‪ :‬أوال ‪ :‬فســخ العقــد الــذي بــن املدعــي واملدعــى عليــه‬\n      ‫الثانــي بخصــوص بيــع املطعــم ثانيـ ًا ‪ :‬ألزمــت املدعــى عليــه الثانــي بإعــادة‬\n      ‫قيمتــه للمدعــي وقدرهــا مليــون ومائــة وعشــرون ألــف ريــال ثالثـاً‪ :‬رددت‬\n\n\n‫‪313‬‬\n\f‫دعــوى املدعــي ضــد املدعــى عليــه األول رابع ـ ًا ‪ :‬صرفــت النظــر عــن‬\n‫دعــوى املدعــي فيمــا زاد علــى مــا حكمــت بــه ‪ ،‬وحكمــت بذلــك‬\n‫وبعــرض احلكــم علــى املدعــي قــرر القناعــة ‪ ،‬هــذا وســوف يتــم تبليــغ‬\n‫املدعــى عليــه الثانــي باحلكــم بواســطة احملضريــن ‪ ،‬وبــاهلل التوفيــق ‪،‬‬\n‫وصلــى اهلل علــى نبينــا محمــد وآلــه وصحبــه وســلم ‪ .‬حــرر يف‬\n                                                             ‫‪1433/08/03‬هـ‬\n‫احلمــد هلل وحــده ‪ ،‬وبعــد ‪ ،‬ففــي يــوم الثالثــاء ‪1433/12/21‬ه ـ فتحــت‬\n‫اجللســة الســاعة ‪ 09 : 15‬وحضــر فيهــا املدعــي أصالــة واملدعــي وكالــة‬\n‫ـاء علــى‬\n        ‫ولــم يحضــر املدعــى عليــه وال وكيلــه رغــم تبلــغ وكيلــه بنـ ً‬\n‫توقيعــه علــى ورقــة التبليــغ وقــد عــادت املعاملــة مــن محكمــة االســتئناف‬\n‫بالريــاض وبرفقهــا القــرار رقــم ‪ 33445838‬وتاريــخ ‪1433/11/03‬ه ـ‬\n‫واملتضمــن مــا نصــه «وبدراســة الصــك وصــورة ضبطــه وأوراق املعاملــة‬\n‫لوحظ ما يلي‪ -1 :‬ورد يف مستهل الصك حضور الطرفني لدى فضيلته‬\n‫وســماعه الدعــوى واإلجابــة بينمــا يف صــورة الضبــط أن ذلــك كان‬\n‫لــدى ســلفه املــازم القضائــي ‪ ...‬فــا بــد مــن أن ذلــك كان لــدى فضيلــة‬\n‫املــازم ا لقضائــي املذكــور ‪ -2‬لــم جنــد فضيلتــه تــا مــا مت ضبطــه‬\n‫ســابق ًا علــى الطرفــن اســتناد ًا للمــادة (‪ )166‬ومــا ذكــره فضيلتــه فهــو‬\n‫اعتمــاد مــا وقــع بعــد التــاوة ولــو اعتــرض عليــه األطــراف ‪ -3‬لــم جنــد‬\n‫وكالــة املدعــى عليــه األول ‪ ...‬رقم ‪ 476600‬يف ‪1433/06/23‬هـ وأيض ًا‬\n‫وكالتــه عــن املدعــى عليــه الثانــي رقــم ‪ 55914‬يف ‪1433/07/26‬ه ـ‬\n‫والصادرتــن مــن كتابــة عــدل الريــاض الثانيــة ‪ -4‬ذكــر املدعــى عليــه‬\n‫وكالــة يف الئحتــه االعتراضيــة املقيــدة باحملكمــة برقــم ‪331481427‬‬\n‫يف ‪1433/08/06‬ه ـ أن املدعــي قــد اســتلم املبيــع مــن أكثــر مــن ثــاث‬\n\n\n                                                                                   ‫‪314‬‬\n\f      ‫ســنني واســتفاد مــن دخلــه خــال تلــك املــدة ولــم جنــد فضيلتــه حتقــق‬\n      ‫مــن ذلــك وأجــرى مــا يلــزم ‪ -5‬ذكــر املدعــى عليــه وكالــة يف الالئحــة‬\n      ‫االعتراضيــة املذكــورة بــأن موكلــه قــد حضــر إلــى احملكمــة ألداء‬\n      ‫اليمــن يف موعــده وقبــل أن ينــادى عليــه شــعر بــآالم ودوخــة نتيجــة ارتفــاع‬\n      ‫الضغــط وغــادر احملكمــة إلــى املستشــفى ولــم جنــد فضيلتــه تعــرض‬\n      ‫لذلــك فعلــى فضيلتــه مالحظــة ذلــك ‪ ،‬واهلل املوفق»إ‪.‬ه ـ ‪ ،‬وجوابـ ًا علــى‬\n      ‫مــا ذكــره أصحــاب الفضيلــة بخصــوص امللحوظــة األولــى أنــه جــرى‬\n      ‫العمــل علــى أن إعــام احلكــم أو مــا يســمى بصــك احلكــم يصــدر‬\n      ‫باســم مصــدر احلكــم ويعتبــر حضورهــم الســابق لــدى فضيلــة الســلف‬\n      ‫حضــور ًا حكميـ ًا لــدى اخللــف وأمــا بخصــوص عــرض مــا ســبق ضبطــه‬\n      ‫علــى الطرفــن فقــد نصــت املــادة املشــار إليهــا علــى أنــه إذا كانــت‬\n      ‫الضبــوط موقعــة بتوقيــع القاضــي الســابق علــى توقيعــات املترافعــن‬\n      ‫والشــهود فيعتمدهــا وهــو مــا بينتــه الالئحــة التنفيذيــة يف الفقــرة (‪)3‬‬\n      ‫وهــذا يعنــي أنــه ال يلــزم عــرض مــا ســبق علــى الطرفــن مــا دامــا أنهمــا‬\n      ‫قــد وقعــا علــى الضبــط علم ـ ًا أنــه ســبق وأن جــرى عــرض مــا ســبق‬\n      ‫تدوينــه علــى الطرفــن عنــد بدايــة نظرنــا للقضيــة فلــم يعتــرض أحــد‬\n      ‫منهمــا علــى أقوالــه املدونــة ســابق ًا ولــم يتــم اإلشــارة إلــى ذلــك ســهو ًا‬\n      ‫منــا هــذا وقــد جــرى إرفــاق صــور الــوكاالت املطلوبــة يف امللحوظــة‬\n      ‫الثالثــة أمــا بخصــوص امللحوظــة الرابعــة فأقــول ‪ :‬إنــه ال وجــه ملطالبــة‬\n      ‫املدعــى عليــه بدخــل احملــل خــال فتــرة وجــوده بيــد املدعــي لكــون يــد‬\n      ‫املدعــي علــى املطعــم يــد ضامنــة وقــد نصــت القاعــدة الشــرعية علــى‬\n      ‫أن (اخلــراج بالضمــان) أمــا بخصــوص امللحوظــة األخيــرة فأقــول ‪ :‬إن‬\n      ‫ذلــك الدفــع مــن املدعــى عليــه ال يقبــل إذ أنــه كان بإمكانــه يف حالــة‬\n\n\n‫‪315‬‬\n\f‫صحــة مــا ذكــر أن يرســل وكيلــه وقــت اجللســة ويعتــذر عــن املوعــد‬\n‫ولــو فتــح البــاب ملثــل هــذه الدفــوع ملــا اســتقرت األحــكام خصوصـ ًا وأن‬\n‫املدعــى عليــه قــد حكــم عليــه بالنكــول الشــرعي وفق ـ ًا ملــا يقتضيــه‬\n‫النظــام وفــوق ذلــك ردت اليمــن علــى املدعــي حتري ـ ًا للحــق وعليــه فــا‬\n‫أرى وجاهــة ذلــك الدفــع بتمكينــه مــن بــذل اليمــن وهــو مــا قــرره أهــل‬\n‫العلــم قــال ابــن قدامــة يف املغنــي «وأمــا إذا حلــف ـ أي املدعــي ـ وقضــي‬\n‫لــه فعــاد املدعــى عليــه وبــذل اليمــن لــم يســمع منــه وهكــذا لــو بذلهــا‬\n‫بعــد احلكــم عليــه بنكولــه لــم يســمع ألن احلكــم قــد مت فــا ينقــض‬\n‫كمــا لــو قامــت بينة»إ‪.‬ه ـ ‪ ،‬وعليــه فلــم يظهــر لــي مــا يوجــب العــدول عمــا‬\n‫حكمــت بــه ‪ ،‬وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى‬\n                            ‫آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪1433/12/21‬ه ـ‬\n‫احلمــد هلل وحــده ‪ ،‬وبعــد ‪ ،‬ففــي يــوم االربعــاء ‪1434/03/25‬ه ـ فتحــت‬\n‫اجللســة الســاعة ‪ 09 : 00‬وقــد عــادت املعاملــة مــن محكمــة االســتئناف‬\n‫بالريــاض وبرفقهــا القــرار رقــم ‪ 348512‬وتاريــخ ‪1434/01/11‬ه ـ‬\n‫املتضمــن أنــه لوحــظ أن مــا أجــاب بــه فضيلتــه علــى قــرار الدائــرة‬\n‫غيــر مقنــع وال بــد مــن إجابــة مفصلــة خاصــة علــى املالحظتــن الرابعــة‬\n‫واخلامســة‪.‬إ‪.‬هـ ‪ ،‬وعليــه فأقــول مســتعين ًا بــاهلل ‪ :‬إن مــن ضمــن امللحوظات‬\n‫الســابقة امللحوظــة الثالثــة والتــي كانــت بخصــوص إرفــاق الــوكاالت‬\n‫وقــد مت إجــراء الــازم بخصوصهــا ومع ذلك فقد شــملها وصف أصحاب‬\n‫الفضيلــة بأنــه غيــر مقنــع أمــا بخصــوص امللحوظــة األولــى فأقــول ‪ :‬إن‬\n‫الصــك إمنــا هــو إعــام باحلكــم وال يلــزم موافقتــه النصيــة للضبــط‬\n‫حســب مــا نصــت عليــه املــادة (‪ )164‬مــن نظــام املرافعــات الشــرعية ثــم‬\n‫كيــف ُيســتهل الصــك بلفــظ (لــدي أنــا املــازم القضائــي) والصــك إمنــا‬\n\n\n                                                                                      ‫‪316‬‬\n\f      ‫ُد ِّون علــى لســاني ومــن إمالئــي ولــم يصــدر منــي إال بعــد انتقــال فضيلــة‬\n      ‫املــازم القضائــي وأمــا حضــور الطرفــن لــدي يف اجللســات األولــى‬\n      ‫فيعــد حضــور ًا حكمي ـ ًا يف صــك احلكــم أمــا الضبــط فقــد ُبـ ِّـن فيــه‬\n      ‫تفصيــل ذلــك وأمــا بخصــوص امللحوظــة الثانيــة فقــد ســبق وأن أشــرت‬\n      ‫بــأن العــرض مقيــد إذا لــم يكــن الطرفــان قــد وقعــا علــى الضبــط وهــو‬\n      ‫واضــح مــن نــص املــادة لكــن اســتجابة ألصحــاب الفضيلــة فقــد طلبــت‬\n      ‫حضــور املدعــى عليــه لعــرض مــا ســبق تدوينــه عليــه وقــد حضــر يف هــذه‬\n      ‫اجللســة املدعــى عليــه وكالــة ‪...‬وبعــرض مــا ســبق تدوينــه عليــه أقــر بــأن‬\n      ‫هــذه أقــوال موكلــه أمــا املدعــي فقــد ســبق العــرض عليــه كمــا هــو‬\n      ‫مبـ َّـن يف ضبــط القضيــة أمــا بخصــوص امللحوظــة الرابعــة فــإن ما ذكره‬\n      ‫املدعــى عليــه مــن أن املدعــي قــد اســتفاد مــن دخــل احملــل خــال الفتــرة‬\n      ‫املاضيــة فأقــول كمــا ســبق وأن بينــت بــأن هــذا ال وجــه ملطالبــة املدعــى‬\n      ‫عليــه بــه إذ أن ذلــك يعــد مــن النمــاء املنفصــل وقــد نــص الفقهــاء علــى أن‬\n      ‫النمــاء املنفصــل يف وقــت اخليــار هــو للمشــتري ألن العــن مــن ضمانــه قــال‬\n      ‫ابــن قدامــة يف املغنــي ‪( :‬ومــا يحصــل مــن غــات املبيــع ومنائــه املنفصــل‬\n      ‫يف مــدة اخليــار فهــو للمشــتري أمضيــا العقــد أم فســخاه قــال أحمــد ‪ :‬مــن‬\n      ‫فوهِ ــب لــه مــالٌ قبــل التفــرق ثــم اختــار البائــع العبــد فاملــال‬\n                                                                              ‫اشــترى عبــد ًا ُ‬\n      ‫للمشــتري وقــال الشــافعي إن أمضيــا العقــد) إلــى أن قــال ‪( :‬ولنــا قــول‬\n      ‫النبــي صلــى اهلل عليــه وســلم ‪« :‬اخلــراج بالضمــان» قــال الترمــذي هــذا‬\n      ‫حديــث صحيــح ‪ .‬وهــذا مــن ضمــان املشــتري فيجــب أن يكــون خراجــه‬\n      ‫لــه وألن امللــك ينتقــل بالبيــع علــى مــا ذكرنــا فيجــب أن يكــون منــاؤه‬\n      ‫لــه كمــا بعــد انقضــاء اخليار)‪.‬إ‪.‬ه ـ ‪ ،‬أمــا بخصــوص امللحوظــة اخلامســة‬\n      ‫فأقــول إن املدعــى عليــه قــد قضــي بنكولــه وقــد ســبق وأن بينــت كالم‬\n\n\n‫‪317‬‬\n\f‫أهــل العلــم أن اخلصــم ال ميكــن مــن أداء اليمــن بعــد احلكــم بنكولــه‬\n‫لكــن اســتجابة ألصحــاب الفضيلــة فقــد قــررت مناقشــة املدعــى عليــه‬\n‫عــن ذلــك ‪ ،‬وبســؤاله عــن ذلــك قــال لقــد حضــر موكلــي إلــى احملكمــة‬\n‫يف وقــت اجللســة التــي قضــي فيهــا بنكولــه والتــي كانــت يــوم األربعــاء‬\n‫‪1433/07/30‬ه ـ ولكــن أحــس بتعــب فغــادر احملكمــة هكــذا قــال‬\n‫فســألته هــل مت إبــاغ أحــد موظفــي املكتــب بذلــك فقــال ســوف أراجــع‬\n‫موكلــي وأجيــب يف اجللســة القادمــة ويف جلســة أخــرى حضــر املدعــي‬\n‫أصالــة واملدعــى عليــه الثانــي أصالــة وبســؤال املدعــى عليــه الثانــي عــن‬\n‫حضــوره يف تاريــخ ‪1433/07/30‬ه ـ فقــال ‪ :‬لقــد حضــرت ثــم غــادرت‬\n‫احملكمــة بســبب اإلعيــاء وبســؤاله عــن املبالــغ املســتلمة قــال ‪ :‬مــا‬\n‫ذكــره املدعــي صحيــح فقــد اســتلمت مبلــغ تســعمائة وعشــرين ألــف‬\n‫ريــال نقــد ًا ومائــة ألــف ريــال مديونيــة علــى املطعــم ومبلــغ ســتة وثالثــن‬\n‫ألــف ريــال فاتــورة مــاء ومبلــغ أربعــة وعشــرين ألــف ريــال فاتــورة كهربــاء‬\n‫وأربعــن ألــف ريــال اســتلمتها نقــد ًا هكــذا قــال وحيــث األمــر مــا ُذكــر‬\n‫وألن إقــراره بعــد نكولــه ليــس لــه أثــر يف احلكــم لــذا فلــم يظهــر لــي‬\n‫مــا يوجــب العــدول عمــا حكمــت بــه وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى‬\n  ‫نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪ 1434/04/02‬ه ـ ‪.‬‬\n‫احلمــد هلل وحــده وبعــد فقــد اطلعنــا نحــن قضــاة الدائــرة اخلامســة لتمييــز‬\n‫القضايــا احلقوقيــة مبحكمــة االســتئناف بالريــاض علــى املعاملــة‬\n‫الــواردة مــن فضيلــة رئيــس احملكمــة العامــة املســاعد بالريــاض برقــم‬\n‫‪ 34189307‬وتاريــخ ‪1434/4/10‬ه ـ املرفــق بهــا الصــك الصــادر مــن‬\n‫فضيلــة القاضــي باحملكمــة الشيخ‪.../‬املســجل برقــم ‪33364368‬‬\n‫وتاريــخ ‪1433/8/3‬ه ـ اخلــاص بدعوى‪(.../‬تركــي اجلنســية) ضــد‪.../‬و‬\n\n\n                                                                                       ‫‪318‬‬\n\f      ‫‪(...‬تركــي اجلنســية)يف مبلــغ مــن املــال علــى الصفــة املوضحــة يف الصــك‬\n      ‫واملتضمــن حكــم فضيلتــه كمــا هــو موضــح بالصــك وباالطــاع علــى‬\n      ‫ـاء‬\n      ‫مــا أجــاب بــه فضيلــة القاضــي وأحلقــه بالصــك وصــورة ضبطــه بنـ ً‬\n      ‫علــى قرارنــا رقــم ‪ 348512‬وتاريــخ ‪1434/1/11‬ه ـ لــم يظهــر مــا يوجــب‬\n      ‫االعتــراض علــى احلكــم بعــد اإلجــراء األخيــر‪.‬واهلل املوفــق وصلــى اهلل‬\n                                       ‫علــى نبينــا محمــد وآلــه وصحبــه وســلم ‪.‬‬\n\n\n\n\n‫‪319‬‬\n\f                       ‫كشاف املوضوعات‬\n\n‫الصفحة‬                       ‫املوضوع‬                        ‫التصنيف‬   ‫م‬\n\n\n  ‫‪7‬‬          ‫الفريق العلمي ملجموعة األحكام القضائية‬          