لدعى عليه بإعادة املبلغ الذي‬\n ‫‪209‬‬      ‫تسلمه مقابل شراء عقار لكون األرض املفرغة له‬            ‫بيع‬     ‫‪30‬‬\n                       ‫غير التي وقع عليها العقد‬\n\n\n            ‫مطالبة املدعي بإلزام الشركة املدعى عليها‬\n             ‫بتعويضه عن سيارته املصدومة والتي قامت‬\n ‫‪218‬‬                                                             ‫بيع‬     ‫‪31‬‬\n         ‫الشركة املدعى عليها ببيعها دون إذنه لكون العقد‬\n                   ‫بينهما إجارة منتهية بالتمليك‬\n\n\n         ‫مطالبة املدعي بإثبات شراء العقار من املدعى عليه‬\n ‫‪251‬‬                                                             ‫بيع‬     ‫‪32‬‬\n                  ‫وتسليمه الصك اخلاص بذلك‬\n\n\n         ‫مطالبة املدعي بإلزام املدعى عليه بدفع قيمة األغنام‬\n ‫‪256‬‬                                                             ‫بيع‬     ‫‪33‬‬\n                        ‫التي قام بشرائها منه‬\n\f‫الصفحة‬                        ‫املوضوع‬                          ‫التصنيف‬   ‫م‬\n\n\n         ‫مطالبة املدعي بإلزام املدعى عليه بدفع باقي قيمة‬\n ‫‪261‬‬                                                             ‫بيع‬     ‫‪34‬‬\n                     ‫اإلبل التي اشتراها منه‬\n\n\n          ‫مطالبة املدعي بإلزام املدعى عليه بإبطال عقد بيع‬\n ‫‪270‬‬     ‫العقار الذي مت بينهما وإعادة املبلغ الذي استمله منه‬     ‫بيع‬     ‫‪35‬‬\n              ‫إلخالله بالشرط الذي اتفقا عليه عند البيع‬\n\n\n          ‫مطالبة املدعي بإلزام املدعى عليه بإعادة اجلزء من‬\n ‫‪276‬‬       ‫قيمة العقار الذي دفعها له حيث تبني أن األرض‬           ‫بيع‬     ‫‪36‬‬\n                         ‫وهمية وال وجود لها‬\n\n\n           ‫مطالبة املدعي بإلزام املدعى عليه بإعادة قيمة‬\n          ‫العقار الذي اشتراه منه حيث تبني أن العقار يقع‬\n ‫‪283‬‬                                                             ‫بيع‬     ‫‪37‬‬\n         ‫ضمن مخطط للدولة وقد وزعت األراضي املوجودة‬\n                         ‫فيه على املواطنني‬\n\n\n          ‫مطالبة املدعي بإلزام املدعى عليه باألرش ‪،‬حيث‬\n ‫‪287‬‬      ‫تبني وجود نقص يف مساحة األرض التي اشتراها‬              ‫بيع‬     ‫‪38‬‬\n                              ‫منه‬\n\n\n           ‫مطالبة املدعي بإلزام املدعى عليه برد ثمن قيمة‬\n ‫‪294‬‬                                                             ‫بيع‬     ‫‪39‬‬\n              ‫السيارة التي اشتراها لوجود عيوب فيها‬\n\n\n         ‫مطالبة املدعي بإلزام املدعى عليه بفسخ العقد الذي‬\n ‫‪304‬‬      ‫بينهما اخلاص بشراء مطعم إلخالل املدعى عليه‬             ‫بيع‬     ‫‪40‬‬\n                        ‫ببعض بنود العقد‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"17250706-b6cd-5618-b1f0-019e3dec82ff","source_page_start":304,"source_page_end":324,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"eb1f7e89f4bde4c9bcf61524a5aeada8da543c77ebf7bdcb4909d0ba120a2757","normalized_text_hash":"6c0efe273270c153f5f7669da93d4566fb7849f829872e79dac51511e21f4775","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v1-p304-33364368"},{"id":"b2126bd6-a070-5f83-b3c9-a7bafdf697df","document_type":"judgment","category":"judicial","subcategory":"general","title":"حادث مروري -دهس رجل عابر للطريق -أرش إصابة -االعتماد على تقرير املرور ملعرفة املتسبب يف احلادث -االعتماد على التقرير الطبي لبيان نسب اإلصابة والعجز -إثبات اإلدانة باإلقرار -التنازل عن جزء من الدية -اإللزام بدفع مقابل أرش اإلصابات -الرجوع على العاقلة يف األروش .","document_number":"344087","case_number":"32389287","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة مبكة املكرمة","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/2/18","year":"1434","subject":"حادث مروري -دهس رجل عابر للطريق -أرش إصابة -االعتماد على تقرير املرور ملعرفة املتسبب يف احلادث -االعتماد على التقرير الطبي لبيان نسب اإلصابة والعجز -إثبات اإلدانة باإلقرار -التنازل عن جزء من الدية -اإللزام بدفع مقابل أرش اإلصابات -الرجوع على العاقلة يف األروش .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"     ‫تاريخه‪1434/2/18 :‬هـ‬\n                      ‫ُ‬                ‫َر ْق ُم َّ‬\n                           ‫الص ِّك‪344087 :‬‬\n                        ‫َر ْق ُم الدعوى‪32389287 :‬‬\n       ‫رقم قرار التصديق من محكمة االستئناف ‪:‬‬\n                ‫‪ 34232530‬تاريخه‪1434/6/6 :‬هـ‬\n\n\n    ‫حــادث مــروري‪ -‬دهــس رجــل عابــر للطريــق ‪ -‬أرش إصابــة‪ -‬االعتمــاد‬\n    ‫علــى تقريــر املــرور ملعرفــة املتســبب يف احلــادث ‪ -‬االعتمــاد علــى التقريــر‬\n    ‫الطبــي لبيــان نســب اإلصابــة والعجــز‪ -‬إثبــات اإلدانــة باإلقــرار‪ -‬التنــازل‬\n    ‫عــن جــزء مــن الديــة ‪ -‬اإللــزام بدفــع مقابــل أرش اإلصابــات ‪ -‬الرجــوع‬\n                                                          ‫علــى العاقلــة يف األروش ‪.‬‬\n\n\n\n    ‫‪ -1‬مــن جنــى علــى إنســان مبباشــرة لزمــه ضمــان تلــك اجلنايــة ســواء‬\n                ‫بلغــت النفــس أو مــا دونهــا ‪ .‬انظــر الــروض املربــع (ص‪. )646‬‬\n    ‫‪ -2‬مــا قــرره أهــل العلــم مــن األخــذ باحلكومــة واعتبارهــا يف كل جنايــة‬\n                                                         ‫ال مقــدر فيهــا شــرع ًا ‪.‬‬\n    ‫‪ -3‬تعميم رئيس املجلس األعلى للقضاء رقم ‪/192‬ت يف ‪1432/10/‬هـ‬\n\n\n\n\n    ‫ا متجهــا ملقــر‬\n                   ‫ادعــى مقيــم علــى مواطــن أنــه أثنــاء قطعــه الطريــق لي ـ ً‬\n    ‫عملــه نظــر عــن ميــن اخلــط فــرأى ســيارة بعيــدة ميكنــه أن يقطــع الطريــق‬\n    ‫قبــل وصولهــا ومــن حــن أن وضــع قدمــه علــى الطريــق وقــد تفاجــأ‬\n    ‫بصــدم املدعــى عليــه لــه‪ -‬وقــد شــاهد املدعــى عليــه قبيــل صدمــه وهــو‬\n    ‫يتكلــم باجلــوال ‪ -‬أغمــي علــى املدعــي مــن جــراء الصــدم ‪ -‬أصيــب‬\n\n‫‪5‬‬\n\f‫املدعــي بكســور يف الرجلــن والظهــر وكســر ســتة أســنان ‪ -‬طلــب‬\n‫املدعــى إلــزام املدعــى عليــه بدفــع ارش اإلصابــات وديــة األســنان الســتة‬\n‫‪ -‬صــادق املدعــى عليــه علــى وقــوع احلــادث وانــه كان يســير بســرعة ‪80‬‬\n‫كــم ‪ -‬دفــع املدعــى عليــه بــأن احلــادث وقــع عنــد منعطــف ولــم يشــاهد‬\n‫املدعــي كمــا أن املدعــي لــم يتأكــد مــن خلــو الطريــق مــن الســيارات‬\n‫أثنــاء عبــوره لــذا فــإن املدعــى مشــترك بالنصــف يف نســبة اخلطــأ حســب‬\n‫تقريــر املــرور ‪ .‬قــرر املدعــى عليــه بــأن اإلصابــات التــي حلقــت املدعــي‬\n‫منــه ســوى األســنان فلــم ينكســر منهــا شــيء جــراء الصــدم ‪ -‬قــرر‬\n‫املدعــي أن الصحيــح مــا جــاء يف دعــواه وأن أســنانه الســتة كســرت‬\n‫بســبب صــدم املدعــى عليــه وأقــر أنــه ليــس لديــه بينــه وطلــب ميــن املدعــى‬\n‫عليــه علــى نفــي ذلــك ‪ -‬نــكل املدعــى عليــه عــن أداء اليمــن وطلــب‬\n‫ردهــا علــى املدعــي ‪ -‬اســتعد املدعــي باحللــف ثــم اتفــق الطرفــان علــى أن‬\n‫يتحمــل املدعــى عليــه ديــة ثــاث أســنان ويتنــازل املدعــي عــن ديــة الثــاث‬\n‫األخــرى ‪ -‬جــرى الرجــوع إلــى محضــر االنتقــال واملعاينــة ‪ -‬كمــا جــرى‬\n‫الرجــوع إلــى تقريــر املــرور املتضمــن إدانــة املدعــى عليــه بنســبة اخلطــأ‬\n‫‪ %50‬لألســباب املذكــورة ومــن أهمهــا الســرعة الزائــدة يف منطقــة عمــل‬\n‫(محــات جتاريــة وورش ســيارات) ‪ -‬جــرى الرجــوع إلــى التقريــر الطبــي‬\n‫املتضمــن بيــان اإلصابــات التــي حلقــت باملدعــي ونســبة العجــز ‪ -‬كمــا‬\n‫جــرى الرجــوع إلــى تقديــر مقــدري الشــجاج ألروش اإلصابــات التــي‬\n‫حلقــت باملدعــي ‪ -‬صــدر احلكــم بإلــزام املدعــى عليــه بــأن يدفــع للمدعــي‬\n‫مائتــن وتســعة وخمســن الفـ ًا وخمســمائة ريــال مقابــل أروش اإلصابــات‬\n‫التــي حلقــت باملدعــي وديــة األســنان الثــاث ‪ -‬كمــا ثبــت تنــازل املدعــي‬\n‫عــن ديــة الثــاث أســنان األخــرى ‪ -‬جــرى إفهــام املدعــى عليــه بــأن لــه‬\n\n\n                                                                                      ‫‪6‬‬\n\f    ‫الرجــوع علــى عاقلتــه ‪ -‬اعتــرض املدعــى عليــه علــى احلكــم ‪ -‬صــدق‬\n    ‫احلكــم مــن محكمــة االســتئناف ‪ -‬جــرى تســليم املبلــغ احملكــوم بــه‬\n                                                     ‫وبذلــك انتهــت القضيــة ‪.‬‬\n\n\n\n\n    ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ...‬القاضــي يف احملكمــة العامــة‬\n    ‫مبكــة املكرمــة وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس‬\n    ‫احملكمــة العامــة مبكــة املكرمــة برقــم ‪ 32389287‬وتاريــخ‬\n    ‫‪ 1432/09/02‬ه ـ املقيــدة باحملكمــة برقــم ‪ 321137267‬وتاريــخ‬\n    ‫‪ 1432/09/01‬ه ـ حضــر ‪...‬هنــدي اجلنســية مبوجــب اإلقامــة رقــم‬\n    ‫ا بواســطة‬   ‫‪...‬كمــا حضــر ‪...‬بالســجل املدنــي رقــم ‪...‬فأدعــى األول قائ ـ ً‬\n    ‫مترجــم احملكمــة ‪...‬مبوجــب اإلقامــة رقــم ‪...‬أننــي كنــت أســير علــى‬\n    ‫ا الســاعة العاشــرة قاطع ـ ًا شــارع اجلزائــر بالعتيبيــة عرض ـ ًا‬ ‫قدمــي لي ـ ً‬\n    ‫متجه ـ ًا إلــى ورشــة كفيلــي مقــر عملــي و قبــل أن أضــع قدمــي مــن‬\n    ‫الرصيــف املتوســط بــن اخلطــن اآلتــي والذاهــب نظــرت عــن ميــن اخلــط‬\n    ‫الــذي أقطعــه فرأيــت ســيارة بعيــدة ميكننــي أن أقطــع الطريــق قبــل‬\n    ‫وصولهــا ومــن حــن أن وضعــت قدمــي إال وأنــا أفاجــئ باملدعــى عليــه‬\n    ‫هــذا احلاضــر علــى ســيارته يصدمنــي بســيارته ففقــدت الوعــي ونقلــت‬\n    ‫إلــى املستشــفى ووقعــت بــي إصابــات متعــددة منهــا كســور يف الرجلــن‬\n    ‫والظهــر وكســر ســتة مــن أســناني وغيــر ذلــك ممــا يف التقريــر الطبــي‬\n    ‫الصــادر مــن مستشــفى ‪...‬علمــا انــه كان يتكلــم بجوالــه قبيــل صدمــه‬\n    ‫ال إيــاه‬\n           ‫إيــاي أطلــب احلكــم علــى املدعــى عليــه بــأرش إصاباتــي ســائ ً‬\n    ‫اإلجابــة عــن دعــواي هــذه فعرضتهــا علــى املدعــى عليــه قــال مــا ذكــره‬\n\n‫‪7‬‬\n\f‫املدعــي مــن أننــي كنــت أســير علــى شــارع اجلزائــر وانــه كان قاطعــا‬\n‫لــه عرض ـ ًا وصدمتــه بســيارتي صحيــح وهــذا عنــد منعطــف الشــارع‬\n‫قــرب ســوق ‪ ...‬فلمــا انعطفــت ولــم اســتطع تفاديــه وال كبــح الســيارة بــل‬\n‫صدمتــه بســرعة الســيارة ‪ 80‬كلــم ولســت أنــا املتســبب وحــدي باحلــادث‬\n‫بــل هــو مشــترك بينــي وبينــه كمــا قــرره املــرور ومــا ذكــره أن الســاعة‬\n‫ا صحيــح ولــم أكــن أتصــل باجلــوال وصحيــح أن‬          ‫كانــت العاشــرة لي ـ ً‬\n‫اإلصابــات املذكــورة مــن جــراء صدمــي لــه ســوى األســنان فلــم ينكســر‬\n‫منهــا شــيء بــل صدمتــه ووقــع علــى ظهــره فالصدمــة ال تقتضــى كســر‬\n‫أســنانه هكــذا أجــاب وبعرضــه علــى املدعــي قــال بــل الصحيــح مــا‬\n‫ذكرتــه أو ًال وقــد ســقطت أســناني مــن جــراء احلــادث وليــس لــدي بينــة‬\n‫علــى ذلــك وأطلــب ميــن املدعــى عليــه علــى نفيــه ‪ .‬واحلــادث ســببه مــن‬\n‫املدعــى عليــه وليــس مشــترك ًا بينــي و بينــه وبعرضــه علــى املدعــى عليــه‬\n‫قــال لســت مســتعدا باليمــن ولــو حلــف املدعــي فــان مســتعد لتســلميه‬\n‫ديتهــا وبعرضــه علــى املدعــي قــال أنــا مســتعد باليمــن ثــم اتفقــا أن‬\n‫يتحمــل املدعــى عليــه ديــة ثالثــة أســنان ويتنــازل املدعــي عــن ديــة الثــاث‬\n‫األخــرى هكــذا اتفقــوا ثــم أطلعــت علــى أوراق املعاملــة فرأيــت منهــا‬\n‫محضــر االنتقــال واملعاينــة علــى ص ‪ 2‬ملــف التحقيــق املرفــق لفــه (‪)1‬‬\n‫هــذا نصــه املوقــع واملعاينــة املوقــع والوصفيــة املوقــع بالعتيبيــة شــارع‬\n‫‪...‬مكــون مــن مســارين وقاطــع و احلــادث عبــارة عــن دهــس شــخص‬\n‫مــن قبــل ســيارة مــن نــوع فــورد ‪ 97‬فضــي اللــون رقــم اللوحــة ‪ ...‬حيــث‬\n‫إن الســائق كان يســير بســرعة عاليــة يف شــارع اجلزائــر وعــدم أخــذ‬\n‫احليطــة واحلــذر مــن قبــل املدهــوس بقطــع الطريــق قبــل التأكــد مــن‬\n‫خلــوه حصــل االصطــدام بالشــخص يف املســار األيســر املــوازي للرصيــف‬\n\n\n                                                                                      ‫‪8‬‬\n\f    ‫املوقــع بالســيارة الركــن األيســر األمامــي مــن الرفــرف األيســر األمامــي‬\n    ‫‪ .‬كيفيــة وقــوع احلــادث ‪ :‬باملعاينــة وتتبــع اآلثــار أن احلــادث وقــع نتيجــة‬\n    ‫الســرعة الزائــدة مــن قبــل الســائق وعــدم أخــذ احليطــة واحلــذر مــن قبــل‬\n    ‫املدهــوس وعــدم التأكــد مــن خلــو الطريــق مــن الســيارات ممــا أدى‬\n    ‫إلــى اصطــدام الســيارة بالشــخص بالركــن األمامــي األيســر ‪ ،‬أســباب‬\n    ‫احلــادث الســرعة الزائــدة مــن الســائق وعــدم أخــذ احليطــة واحلــذر مــن‬\n    ‫قبــل املدهــوس نتائــج احلــادث نتــج عــن احلــادث إصابــة املدهــوس وتلفيــات‬\n    ‫بالركــن األيســر األمامــي مــع الرفــرف األيســر األمامــي ‪...‬ثــم أطلعــت‬\n    ‫علــى محضــر تقريــر املســؤولية يف احلــادث ص ‪ 8‬مــن امللــف نفســه هــذا‬\n    ‫نصــه وبعــد اإلطــاع علــى مجريــات التحقيــق واملعاينــة والكروكــي‬\n    ‫باحلــادث تضــح اآلتــي‪ :‬أو ًال يــدان الســائق باحلــادث بنســبة (‪ )%50‬وذلــك‬\n    ‫لألســباب التاليــة ‪1:‬ـ الســرعة الزائــدة التــي كان يســير بهــا قبــل احلادث‬\n    ‫بدليــل مــا ذكــره مبلــف التحقيــق ص ‪ 5‬مــن انــه كان يســير بســرعة‬\n    ‫‪ 80‬كلــم بينمــا الطريــق محــدد لــه ســرعة قصــوى ‪ 60‬كلــم ‪2‬ـ املوقــع‬\n    ‫بــه محــات جتاريــة علــى جانبيــة و ورش إصــاح للســيارات وكان‬\n    ‫الواجــب عليــه أخــذ أقصــى درجــات احليطــة واحلــذر ‪3‬ـ عــدم أخــذ احليطــة‬\n    ‫واحلــذر أثنــاء القيــادة‪ .‬ثانيـ ًا يــدان املدهــوس باحلــادث بنســبة (‪ )%50‬وذلــك‬\n    ‫لألســباب التاليــة ‪1‬ـ قطعــه الطريــق دون التأكــد من خلوه من الســيارات‬\n    ‫‪2‬ـ كان الواجــب عليــه الوقــوف باجلزيــرة الوســطية والتأكــد مــن جهــة‬\n    ‫اليمــن حتــى يتــم التأكــد مــن عــدم وجــود ســيارات ومــن ثــم العبــور‬\n    ‫بســام ‪3‬ـ عــدم أخــذ احليطــة واحلــذر أثنــاء عبــور الطريــق‪ .‬وحفظـ ًا للواقــع‬\n    ‫دون هــذا احملضــر وبــاهلل التوفيــق ضابــط التحقيــق املــازم األول ‪...‬و‬\n    ‫ضابــط القضيــة نقيــب ‪...‬و مديــر قســم احلــوادث املكلــف الرائــد ‪...‬أ‪.‬ه ـ‬\n\n\n‫‪9‬‬\n\f‫ثــم أطلعــت علــى التقريــر الطبــي الصــادر مــن مستشــفى ‪...‬برقــم ‪...‬يف‬\n‫‪1433/7/12‬ه ـ ويتضمــن أنــه بعــد الكشــف علــى املدعــي وقــت دخولــه‬\n‫يف ‪143/1/8‬ه مــن قبــل اللجنــة املكلفــة بذلــك اثــر حــادث مــروري قــدمي‪.‬‬\n‫املريــض يعانــي مــن كســر يف عظمتــي الســاق اليمنــى ملتحــم حاليــا بعــد‬\n‫ان مت تثبيتــه مبســمار نخاعــي لــم يتــرك أي إعاقــة وظيفيــة ونســبة العجــز‬\n‫لهــا (‪ )%3‬كســر يف الطبــق الطنبوبــي للســاق اليســرى ملتحــم التحــام‬\n‫معيــب نتــج عنــه قصــر يف الطــرف الســفلي مبقــدار ‪ 2،95‬ســم مــع‬\n‫خشــونة متقدمــة يف مفصــل الركبــة اليســرى وتــورم يف الركبــة وحتــدد‬\n‫باحلركــة العطــف واالنبســاط بــن (‪ 0‬ـ ‪ )95‬درجــة وهــي عاهــة مســتدمية‬\n‫نســبتها (‪ )%53‬كســر يف الفقــرة القطنيــة األولــى ملتحمــة بعــد تثبيتــه‬\n‫بأربعــة مســامير وقضيبــن وعشــر غــرز نســبة العجــز (‪ )%15‬ومبراجعــة‬\n‫امللــف الطبــي تبــن عــدم عرضــه علــى أخصائــي الفكــن أثنــاء فتــرة‬\n‫تنوميــه باملستشــفى (بالنســبة للمســالك ) تبــن أن مــا لديــه مــن بقايــا‬\n‫عجــز حســب احلــادث واإلصابــات (لديــه ضعــف يف االنتصــاب مــن الفئــة‬\n‫األولــى تقــدر بنســبة العجــز (‪ )%10‬عــداه مــن منفعــة البــول ســليم بالنســبة‬\n‫لألســنان بالكشــف الطبــي لــم يتبــن وجــود أي ســن أمامــي لديــه علمــا‬\n‫أن اإلصابــة بتاريــخ ‪1432/1/8‬ه ـ واملريــض يدعــى وجــود أســنان أماميــة‬\n‫لديــه العلويــة والســفلية قبــل احلــادث ولكــن ال ميكــن حتديــد وجــود‬\n‫األســنان ســابقا مــن عدمــه نظــر ًا لتأخــر الكشــف عليــه حتــى تاريخــه‬\n‫علمـ ًا انــه بعــد ســتة أشــهر مــن فقــدان الســن يختفــي أي دليــل إشــعاعي‬\n‫علــى وجــوده أو ســريري ويعتمــد التقريــر املبدئــي للطــوارئ لفقــد‬\n‫األســنان دون حتديــد العــدد نســبة العجــز الكليــة (‪+ %15 +%53 +%3‬‬\n‫‪ %81 = %10‬إحــدى وثمانــون باملائــة فقــط الطبيــب املعالــج دـ ‪ ،...‬دـ ‪،...‬‬\n\n\n                                                                                     ‫‪10‬‬\n\f     ‫دـ ‪...‬أ‪.‬ه ـ ثــم أطلعــت علــى تقريــر مقــدري الشــجاج رقــم ‪ 321217613‬يف‬\n     ‫‪1433/8/4‬ه ـ هــذا نصــه بعــد االطــاع علــى التقاريــر الطبيــة املتعلقــة‬\n     ‫باملصــاب ‪...‬وبعــد معاينتــه وجــد اآلتــي ‪-1‬كســر بعظمتــي الســاق‬\n     ‫اليمنــى ملتحــم ويقــدر لــه ‪ 12000‬اثنــا عشــر ألــف ريــال شــرعا ‪-2‬نســبة‬\n     ‫عجــز للســاق اليمنــى ‪ %3‬ويقــدر لــه ‪ 4500‬أربعــة أالف وخمســمائة ريــال‬\n     ‫حكومــة ‪ -3‬كســر يف الطبــق الطنبوبــي للســاق اليســرى ملتحــم ويقــدر‬\n     ‫لــه ‪ 9000‬تســعة أالف ريــال حكومــة ‪ -4‬قصــر يف الطــرف الســفلي‬\n     ‫األيســر مبقــدار ‪ 2.75‬ســم ويقــدر لــه ‪ 4500‬أربعــة أالف وخمســمائة‬\n     ‫ريــال حكومــة ‪ -5‬حتــدد يف حركــة العطــف واالنســياب للحركــة مــع‬\n     ‫خشــونة وتــورم يف الركبــة اليســرى وهــي عاهــة مســتدمية ونســبة العجــز‬\n     ‫فيهــا ‪ %53‬ويقــدر لهــا ‪ 79500‬تســعة وســبعون ألــف وخمســمائة ريــال‬\n     ‫‪-6‬كســر يف الفقــرة القطنيــة األولــى ملتحــم ويقــدر لــه ‪ 30000‬ثالثــون‬\n     ‫ألــف ريــال حكومــة ‪ -7‬نســبة العجــز للفقــرة القطنيــة ‪ %15‬ويقــدر‬\n     ‫لهــا ‪ 45000‬خمســة وأربعــون ألــف ريــال حكومــة ‪ -8‬نســبة العجــز يف‬\n     ‫االنتصــاب ‪ %10‬ويقــدر لــه ‪ 30000‬ثالثــون ألــف ريــال حكومــة أ‪.‬ه ـ‬\n     ‫وبعــد التأمــل والنظــر يف الدعــوى واإلجابــة ونظــر ًا إلقــرار املدعــى عليــه‬\n     ‫أن ســرعته كانــت زائــدة عــن املســموح بــه يف ذلــك الشــارع وأنــه كان‬\n     ‫يف موضــع انعطــاف مــن الشــارع فمثــل هــذا يجــب أن يتأنــى يف ســيره‬\n     ‫ويخفــض ســرعته حتســب ًا ألي شــيء رمبــا يكــون أمامــه مــن إنســان‬\n     ‫أو ســيارة ونظــر ًا إلقــرار املدعــى عليــه مبباشــرة صــدم املدعــي نظــر ُا ملــا‬\n     ‫قــرره أهــل العلــم أن مــن جنــى علــى إنســان مبباشــرة لزمــه ضمــان تلــك‬\n     ‫اجلنايــة ســواء بلغــت النفــس أو مــا دونهــا ينظــر الــروض املربــع ص ‪646‬‬\n     ‫ونظــر ًا ملــا ورد يف التقريــر الطبــي مــن اإلفــادة عــن اجلنايــة الواقعــة علــى‬\n\n\n‫‪11‬‬\n\f‫املدعــي مــن جــراء احلــادث املوصــوف وتأسيس ـ ًا علــى مــا قــدره مقــدر‬\n‫الشــجاج باحملكمــة ألرش تلــك اجلنايــة ونظــر ًا ملــا قــرره أهــل العلــم‬\n‫مــن األخــذ باحلكومــة واعتبــاره يف كل جنايــة ال مقــدر فيهــا شــرع ًا‬\n‫وبعــد اطالعــي علــى تعميــم رئيــس املجلــس األعلــى للقضــاء رقــم ‪... /...‬‬\n‫يف ‪1432/10/9‬ه ـ بــأن الديــة الكاملــة ثالثمائــة ألــف ريــال ونظــر ًا‬\n‫ملــا اتفــق عليــه الطرفــان يف شــأن األســنان وألن ديتهــا تســاوي خمســة‬\n‫وأربعــن ألف ـ ًا مضافــة إلــى املبلــغ املقــدر مــن مقــدري الشــجاج ليصبــح‬\n‫مائتــن وتســعة وخمســن ألفــا وخمســمائة ريــال عليه فقــد حكمت على‬\n‫املدعــي عليــه أن يســلم املدعــي مئتــن وتســعة وخمســن ألفـ ًا وخمســمائة‬\n‫ريــال (‪ )259500‬ريــال وثبــت لــدي تنــازل املدعــي عــن ديــة أســنانه الثالثــة‬\n‫األخــرى وأفهمــت املدعــى عليــه أن لــه أن يرجــع إلــى عاقلتــه وبعرضــه‬\n‫علــى املدعــى عليــه لــم يقنــع بــه فأفهمتــه بتعليمــات االســتئناف وبــاهلل‬\n‫التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪.‬‬\n                                                     ‫حــرر يف ‪ 1434/02/11‬ه ـ‬\n‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده وبعــد فقــد‬\n‫عــادت املعاملــة مــن محكمــة االســتئناف باخلطــاب رقــم ‪341217613‬‬\n‫يف ‪1434/4/20‬ه ـ وبرفقــه القــرار رقــم ‪ 34185583‬يف ‪1434/4/13‬ه ـ‬\n‫املتضمــن وبدراســة احلكــم و صــورة ضبطــه والئحتــه االعتراضيــة تقــرر‬\n‫باألكثريــة إعادتهــا لفضيلــة حاكمهــا ملالحظــة مــا يلــي ‪1‬ـ ان املبلــغ‬\n‫احملكــوم بــه أكثــر ممــا هــو مقــرر يف قــرار مقــدر الشــجاج ‪2‬ـ ذكــر‬\n‫تقريــر املــرور أن نســبة اإلدانــة علــى املدعــى عليــه خمســن باملائــة‪%50‬‬\n‫فهــل ثبــت لــدى القاضــي وحكــم باحلــق اخلــاص بنــاء علــى هــذه النســبة‬\n‫فعلــى القاضــي إعــادة النظــر بحضــور الطرفــن واهلل التوفيــق وصلــى‬\n\n\n                                                                                     ‫‪12‬‬\n\f     ‫اهلل علــى نبينــا محمــد وعلــى اهلل و صحبــه وســلم أ‪.‬ه ـ وعليــه أجيــب‬\n     ‫أصحــاب الفضيلــة وفقهــم اهلل عــز وجــل بــان حكمــي هــو مجمــوع مــا‬\n     ‫قــدره مقــدرو الشــجاج بإقرارهــم يضــاف إليــه مــا اصطلح عليــه الطرفان‬\n     ‫بشــأن ديــة األســنان الثالثــة وقــدره خمســة وأربعــون ألــف ريــال فاملجمــوع‬\n     ‫هــو مــا حكمــت بــه لكــن املدعــى عليــه انكــر انكســار اســنان‬\n     ‫املدعــي مــن جــراء احلــادث ثــم اتفــق هــو واملدعــي علــى أن يتحمــل املدعــى‬\n     ‫عليــه ثالثــة أســنان ويســقط املدعــي ديــة الثالثــة األخــرى وامــا تقريــر‬\n     ‫املــرور بتصنيــف مســؤولية احلــادث فليــس هــو اعتمــادي بــل اعتمــدت‬\n     ‫املســؤولية كاملــة علــى املدعــى عليــه ملــا أشــرت إليــه مــن أســباب يف‬\n     ‫تســبيب حكمــي وبــاهلل التوفيــق وصلــى اهلل علــى نبينــا محمــد وعلــى‬\n                                    ‫اهلل و صحبــه وســلم حــرر يف ‪1434/5/6‬ه ـ‬\n     ‫احلمــد هلل وحــده ففــي هــذا اليــوم الثالثــاء املوافــق ‪1434/8/23‬ه ـ‬\n     ‫افتتحــت اجللســة وفيهــا حضــر ‪ ...‬ســعودي بســجل مدنــي رقــم ‪...‬بوكالتــه‬\n     ‫عــن ‪...‬هنــدي اجلنســية مبوجــب اإلقامــة ‪...‬بالوكالة رقــم ‪...‬تخوله اإلقرار‬\n     ‫واالســتالم وقــرر بأنــه قــد اســتلم مبلغ ـ ًا قــدره مائتــان وتســعة وخمســون‬\n     ‫ألفــا ً وخمســمائة ريــال مبوجــب الشــيك رقــم ‪ 277294‬ي ‪1434/8/21‬هـ‬\n     ‫الصــادر مــن مصــرف ‪...‬وذلــك مقابــل أرش إصابــة موكلــة ‪...‬وبذلــك‬\n     ‫تكــون القضيــة منتهيــة وصلــى اهلل علــى نبينــا محمــد وعلــى الــه‬\n                                        ‫وصحبــة وســلم حــرر يف ‪1434/8/23‬ه ـ‬\n     ‫احلمــد هلل والصــاة والســام علــى رســول اهلل وبعــد ‪ ...‬نحــن رئيــس‬\n     ‫وقضــاة الدائــرة اجلزائيــة الرابعــة يف محكمــة االســتئناف مبنطقــة‬\n     ‫مكــة املكرمــة جــرى منــا االطــاع علــى الصــك رقــم ‪ 3440876‬وتاريــخ‬\n     ‫‪1434/2/18‬ه ـ الصــادر من فضيلة الشــيخ‪...‬القاضي باحملكمة العامة‬\n\n\n‫‪13‬‬\n\f‫مبكــة املكرمــة ‪ ،‬املتضمــن دعــوى املدعــي ‪...‬هنــدي اجلنســية ضــد‪/‬‬\n‫‪ ،...‬املتهــم بحــادث مــروري‪ ،‬احملكــوم فيــه مبــا دون باطنــه املالحــظ‬\n‫عليــه بقــرار محكمــة االســتئناف ‪ 34185583‬وتاريــخ ‪1434/4/13‬هـ ـ ـ‬\n‫‪ .‬وبدراســة الصــك وصــورة ضبطــه والالئحــة االعتراضيــة تقــرر‬\n‫باألكثريــة املوافقــة علــى احلكــم بعــد اإليضــاح األخيــر‪ ،‬واهلل املوفــق‬\n               ‫وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪.‬‬\n\n\n\n\n                                                                                ‫‪14‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"80f9241f-522e-5e5b-9c5b-24043d5934e7","source_page_start":5,"source_page_end":14,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"9d83eae42cea47f11851f3b183b20fc38f263a4ff1ca653f742b1a1bec1259fb","normalized_text_hash":"c08e1ddc7b3045f2861b3e93d71e6f11d279ca1fc174fee37d2c00c05e4f5bb9","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v10-p5-344087"}]$archive_payload$::jsonb) AS x LIMIT 25
